/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A36 staging source: exact frozen 80-lemma batch; publish after all checks. */
'use strict';
const D=globalThis.RA.D;
const E=(origin,word)=>({origin,prefix:null,root:null,suffix:null,history:[],formationLogic:'',mnemonic:null,note:'Only the stated formation and sense history are asserted.',source:'Etymonline — https://www.etymonline.com/word/'+word.toLowerCase()});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({wrong,right,reason,errorType});
const Q=(w,n,s,prompt,a,b,c,answer,explain,errorType='meaning')=>({id:w+'.q'+n,senseId:w+'.s'+s,errorType,type:'辨义与用法',prompt,options:[a,b,c],answer,explain});

D('fortitude',{etymology:E('Fortitude comes from Latin fortitudo “strength, courage,” from fortis “strong.” It describes courage and endurance in hardship.','fortitude'),contexts:[C('fortitude.s2','危机应对','When the bridge alarm sounded, the nurse showed fortitude by guiding the injured passengers to safety before returning to help the crew.','桥梁警报响起时，护士镇定坚毅地先引导伤员脱险，随后又返回帮助船员。','When the bridge alarm sounded / the nurse showed fortitude / by guiding the injured passengers to safety / before returning to help the crew.','show fortitude 表示在危险或压力下表现坚毅。','面对危险仍帮助他人，体现临危不惧的义项 s2。')],mistakes:[M('The witness showed fortitude by abandoning the injured passengers at the first sign of danger.','The witness showed courage by staying to help the injured passengers despite the danger.','遇险立即抛下伤者体现逃避，而非坚毅勇气。')],quiz:[Q('fortitude',1,1,'Fortitude during a painful treatment means?','courage and endurance','carelessness about all danger','a medical instrument','courage and endurance','s1 指忍受痛苦与困难的坚毅。'),Q('fortitude',2,2,'A person who returns to rescue others during a crisis shows?','moral courage under danger','a lack of concern for anyone','a wish to avoid responsibility','moral courage under danger','s2 指临危时的刚毅勇气。'),Q('fortitude',3,1,'Which situation best demonstrates fortitude?','continuing rehabilitation despite pain and setbacks','quitting immediately after a small inconvenience','ignoring every safety warning','continuing rehabilitation despite pain and setbacks','持久承受痛苦并继续努力体现坚毅。'),Q('fortitude',4,2,'Fortitude is most closely associated with?','bravery and resilience','wealth and status','speed and distance','bravery and resilience','fortitude 强调勇气与承受力。')]});
D('fortnightly',{etymology:E('Fortnightly is formed from fortnight plus -ly. Fortnight is a contraction of “fourteen nights,” and fortnightly means once every two weeks or relating to a two-week period.','fortnightly'),contexts:[C('fortnightly.s1','排班安排','The clinic publishes its rota fortnightly, so staff receive a new schedule every two weeks rather than every Friday.','诊所每两周发布一次值班表，因此员工不是每周五，而是隔周收到新安排。','The clinic publishes its rota fortnightly / so staff receive a new schedule every two weeks / rather than every Friday.','fortnightly 作副词，表示每两周一次。','明确与每周发布对比，体现频率义 s1。')],mistakes:[M('The clinic issues its rota fortnightly, sending a new schedule every single day.','The clinic issues its rota daily, sending a new schedule every single day.','每天发布并非每两周一次。')],quiz:[Q('fortnightly',1,1,'A fortnightly meeting happens?','once every two weeks','every night','once every fourteen years','once every two weeks','fortnightly 作副词表示每两周一次。'),Q('fortnightly',2,2,'A fortnightly magazine is published?','every two weeks','twice each day','once every two months','every two weeks','s2 作定语表示双周刊或双周的。'),Q('fortnightly',3,1,'A fortnight contains how many nights?','fourteen','seven','forty','fourteen','fortnight 原指十四个夜晚。'),Q('fortnightly',4,1,'Choose the natural sentence.','The report is reviewed fortnightly.','The report is fortnightly reviewedly.','The report is reviewed for nightly.','The report is reviewed fortnightly.','副词 fortnightly 修饰 reviewed。')]});
D('fortuitous',{etymology:E('Fortuitous came from Latin fortuitus “happening by chance,” related to fors “chance.” It can mean accidental and, in a common extended use, unexpectedly fortunate.','fortuitous'),contexts:[C('fortuitous.s2','偶遇机会','It was fortuitous that the visiting engineer arrived just as the pump failed; she had the exact replacement part in her van.','来访工程师恰在水泵故障时抵达，真是幸运巧合；她的车里正好有合适的替换零件。','It was fortuitous that the visiting engineer arrived just as the pump failed / she had the exact replacement part / in her van.','fortuitous 作表语形容词，描述偶然而有利的巧合。','工程师偶然赶到且带着零件，符合幸运巧合义 s2。')],mistakes:[M('Their fortuitous meeting was carefully scheduled months in advance and involved no chance at all.','Their planned meeting was scheduled months in advance and involved no chance at all.','提前安排、毫无偶然性不属于 fortuitous。')],quiz:[Q('fortuitous',1,1,'A fortuitous meeting is one that?','happens by chance','is planned to the minute','takes place every year','happens by chance','s1 指偶然发生。'),Q('fortuitous',2,2,'A fortuitous discovery is often?','unexpected and lucky','deliberately concealed','certainly harmful','unexpected and lucky','常见引申义强调偶然带来好处。'),Q('fortuitous',3,1,'Which event is fortuitous?','Finding the needed key by chance just before the door locks.','Ordering the same key from a catalogue weeks earlier.','Losing a key exactly as expected.','Finding the needed key by chance just before the door locks.','偶然找到恰好所需的钥匙是幸运巧合。'),Q('fortuitous',4,2,'“A fortuitous opportunity” suggests an opportunity that is?','unexpectedly advantageous','carefully scheduled and ordinary','impossible to use','unexpectedly advantageous','该用法指意外出现的有利机会。')]});
D('fortuitously',{etymology:E('Fortuitously is the adverb formed from fortuitous plus -ly. It means by chance, often with a fortunate result.','fortuitously'),contexts:[C('fortuitously.s1','临时维修','Fortuitously, the spare filter was still in the workshop, so the crew restored the water system before the shelter opened.','幸运的是，备用滤芯还在车间里，因此工作人员在避难所开放前修好了供水系统。','Fortuitously / the spare filter was still in the workshop / so the crew restored the water system / before the shelter opened.','句首 fortuitously 是评注副词，表示事情偶然且结果有利。','备用件恰好在场并及时解决问题，符合偶然地、幸而义。')],mistakes:[M('The technician fortuitously found the filter because she had hidden it there deliberately the night before.','The technician deliberately placed the filter there the night before.','有意提前放置并非 fortuitously（偶然地）发现。')],quiz:[Q('fortuitously',1,1,'Fortuitously finding a spare means finding it?','by chance, with a useful result','after intentionally hiding it','only after it was destroyed','by chance, with a useful result','fortuitously 指偶然地，常含幸运结果。'),Q('fortuitously',2,1,'Which sentence uses fortuitously naturally?','Fortuitously, the bus arrived just as the rain began.','She fortuitously planned every chance event years ahead.','The fortuitously was under the table.','Fortuitously, the bus arrived just as the rain began.','刚好赶上巴士是偶然有利的结果。'),Q('fortuitously',3,1,'The adverb fortuitously modifies?','the manner in which an event happens','the plural form of a noun','the colour of an object','the manner in which an event happens','副词说明事件发生方式。'),Q('fortuitously',4,1,'If the lost pass turns up fortuitously, it?','appears unexpectedly at a helpful moment','was never lost','was ordered for next year','appears unexpectedly at a helpful moment','意外在有帮助时刻找到体现 fortuitously。')]});
D('fortunately',{etymology:E('Fortunately is formed from fortunate plus -ly. Fortunate comes from Latin fortunatus, related to fortuna “fortune, chance”; the adverb marks a favourable circumstance.','fortunately'),contexts:[C('fortunately.s1','出行安排','Fortunately, the last train was delayed by ten minutes, giving the stranded passengers time to reach the platform.','幸运的是，末班车晚点了十分钟，让滞留乘客有时间赶到站台。','Fortunately / the last train was delayed by ten minutes / giving the stranded passengers time / to reach the platform.','句首 fortunately 表示说话者认为后续情况是有利的。','晚点反而给乘客争取了赶车时间，符合幸亏、幸运地。')],mistakes:[M('Fortunately, the only bridge collapsed and cut off every route out of the valley.','Unfortunately, the only bridge collapsed and cut off every route out of the valley.','道路被切断是坏消息，应使用 unfortunately。')],quiz:[Q('fortunately',1,1,'Fortunately, the keys were found before the doors closed. This means?','luckily, a helpful thing happened','the keys were certainly stolen','the doors closed earlier than planned','luckily, a helpful thing happened','fortunately 表示幸运的是。'),Q('fortunately',2,1,'Which is the best continuation after Fortunately?','a doctor was nearby when help was needed','the rescue boat sank before it arrived','all exits were blocked','a doctor was nearby when help was needed','附近有医生是有利情况。'),Q('fortunately',3,1,'Fortunately most often introduces?','a favourable fact or outcome','a list of ingredients','a direct command','a favourable fact or outcome','该副词常引出令人庆幸的情况。'),Q('fortunately',4,1,'Choose the correct spelling.','Fortunately, everyone reached safety.','Fortunatly, everyone reached safety.','Fortunatefully, everyone reached safety.','Fortunately, everyone reached safety.','正确拼写是 fortunately。','spelling')]});
D('forward-looking',{etymology:E('Forward-looking combines forward and looking. The metaphor of looking ahead gives it the sense “planning for future needs or developments.”','forward-looking'),contexts:[C('forward-looking.s1','城市规划','The council adopted a forward-looking transport plan that reserves land for electric buses and safer walking routes as the population grows.','市议会通过了一项有远见的交通规划，随着人口增长预留电动公交和更安全步行路线用地。','The council adopted a forward-looking transport plan / that reserves land for electric buses and safer walking routes / as the population grows.','forward-looking 作复合形容词修饰 plan。','方案预先考虑未来人口和交通需求，体现前瞻性。')],mistakes:[M('The forward-looking plan ignored projected population growth and provided no space for future transport needs.','The forward-looking plan reserved space for projected population growth and future transport needs.','完全不考虑未来需求与 forward-looking 相反。')],quiz:[Q('forward-looking',1,1,'A forward-looking policy considers?','future needs and likely changes','only events from centuries ago','the view behind the speaker','future needs and likely changes','forward-looking 指有远见、面向未来。'),Q('forward-looking',2,1,'Which is a forward-looking investment?','building capacity for expected future demand','repairing nothing until the system fails','spending only on past ceremonies','building capacity for expected future demand','按预测需求提前建设体现前瞻性。'),Q('forward-looking',3,1,'The hyphen in forward-looking marks?','a compound adjective before a noun','a past-tense verb','a plural ending','a compound adjective before a noun','该词常以连字符构成复合形容词。','grammar'),Q('forward-looking',4,1,'Choose the natural phrase.','a forward-looking strategy','a looking-forward strategy of tomorrow','a forwardly look plan','a forward-looking strategy','forward-looking strategy 是自然搭配。')]});
D('fossilise',{etymology:E('Fossilise is the British spelling of fossilize, formed from fossil plus -ise. Fossil derives from Latin fossilis “dug up,” from fodere “to dig”; the verb can mean preserve as a fossil or become rigid.','fossilise'),contexts:[C('fossilise.s1','地质记录','Mineral-rich water can fossilise wood over long periods, replacing some of its original material while preserving its shape.','富含矿物质的水会在漫长时间里使木材石化，以矿物替代部分原有物质，同时保留其形状。','Mineral-rich water can fossilise wood over long periods / replacing some of its original material / while preserving its shape.','fossilise 作及物动词，表示使成化石。','矿物质逐渐取代木质并保存形状，符合石化义。')],mistakes:[M('The museum fossilised the shell by keeping it soft and unchanged in ordinary tap water.','The museum preserved the shell as a fossil by mineralising its structure.','保持软质且未矿化不构成石化过程。')],quiz:[Q('fossilise',1,1,'To fossilise wood is to?','preserve it through mineral replacement','turn it into fresh leaves','burn it into ash','preserve it through mineral replacement','fossilise 的地质义是使其成为化石。'),Q('fossilise',2,1,'Which spelling is British English?','fossilise','fossalise','fossilisee','fossilise','英式拼法以 -ise 结尾。','spelling'),Q('fossilise',3,1,'What may happen to a buried shell over geological time?','it may fossilise','it may become a fresh flower','it may turn into a cloud','it may fossilise','埋藏贝壳可能在地质过程中石化。'),Q('fossilise',4,1,'The verb fossilise can also figuratively mean to?','make a system rigid and resistant to change','make a schedule flexible','remove all records','make a system rigid and resistant to change','比喻义指使制度僵化。')]});
D('fossilization',{etymology:E('Fossilization is formed from fossilize plus -ation; fossil comes from Latin fossilis “dug up.” It names the formation of fossils and, figuratively, the loss of flexibility or change.','fossilization'),contexts:[C('fossilization.s2','语言习得','The learner’s fossilization of the incorrect verb ending persisted even after years of practice, so the teacher focused on new feedback rather than more repetition.','学习者对错误动词词尾的语言石化持续多年，即使练习后仍未改正，因此教师转而提供新的反馈。','The learner’s fossilization of the incorrect verb ending persisted / even after years of practice / so the teacher focused on new feedback / rather than more repetition.','fossilization 在语言学习中表示错误形式长期固化。','多年后错误仍稳定出现，符合语言石化义 s2。')],mistakes:[M('The learner’s fossilization disappeared immediately after one correction and never recurred.','The learner’s fossilization persisted despite repeated correction.','立即消失且不再出现不符合长期固化的 fossilization。')],quiz:[Q('fossilization',1,1,'Geological fossilization is the process by which?','remains become preserved as fossils','rocks become fresh fruit','a glacier melts overnight','remains become preserved as fossils','s1 指形成化石的过程。'),Q('fossilization',2,2,'In language learning, fossilization is?','a persistent error that resists correction','a learner forgetting every language','a fossil found in a classroom','a persistent error that resists correction','s2 指错误语言形式长期固化。'),Q('fossilization',3,1,'What is the noun form of fossilize?','fossilization','fossilful','fossilously','fossilization','fossilization 是 fossilize 的名词形式。','word-formation'),Q('fossilization',4,2,'A fossilized grammar error is one that?','has become stable and hard to change','was corrected instantly','appears only in a stone','has become stable and hard to change','语言石化错误具有持续性。')]});
D('fossilize',{etymology:E('Fossilize combines fossil and -ize. Fossil comes from Latin fossilis “dug up,” from fodere “dig”; fossilize means to preserve as a fossil or become rigid.','fossilize'),contexts:[C('fossilize.s2','制度僵化','Without regular review, the agency’s procedures began to fossilize, preserving obsolete steps long after the technology had changed.','由于缺乏定期审查，该机构的流程开始僵化；技术早已改变，过时步骤却仍被保留。','Without regular review / the agency’s procedures began to fossilize / preserving obsolete steps / long after the technology had changed.','fossilize 在此是不及物动词的比喻义，表示逐渐僵化。','流程无法随技术变化而更新，体现 s2。')],mistakes:[M('The agency’s procedures fossilized by changing smoothly every week to match new technology.','The agency’s procedures remained flexible by changing smoothly with new technology.','持续灵活地适应变化与 fossilize 的僵化义相反。')],quiz:[Q('fossilize',1,1,'To fossilize a leaf is to?','preserve it as a fossil','make it grow on a living tree','dissolve it in fresh water','preserve it as a fossil','s1 指使成为化石或石化。'),Q('fossilize',2,2,'A rule system that fossilizes?','becomes rigid and resists change','adapts quickly to new needs','vanishes from every record','becomes rigid and resists change','s2 是比喻义“变得僵化”。'),Q('fossilize',3,1,'Which sentence uses fossilize literally?','The buried plant may fossilize over time.','The committee fossilized its meeting at noon.','The fossilize was in the cabinet.','The buried plant may fossilize over time.','埋藏植物可能在地质过程中石化。'),Q('fossilize',4,1,'The ending -ize commonly helps form?','a verb','a plural noun only','a comparative adjective only','a verb','-ize 常用于构成动词。','word-formation')]});
D('fossilized',{etymology:E('Fossilized is the past participle and adjective from fossilize, formed from fossil plus -ize. It describes material preserved as a fossil or, figuratively, a rigid belief or practice.','fossilized'),contexts:[C('fossilized.s2','陈旧惯例','The committee’s fossilized approval process still required paper signatures even though every department had moved to secure digital records.','委员会僵化的审批流程仍要求纸质签名，尽管所有部门都已改用安全数字记录。','The committee’s fossilized approval process still required paper signatures / even though every department / had moved to secure digital records.','fossilized 修饰 process，作比喻形容词表示僵化。','流程未能随数字化更新，符合僵化义 s2。')],mistakes:[M('The fossilized process changed instantly whenever employees suggested a faster method.','The flexible process changed instantly whenever employees suggested a faster method.','能够迅速改进的流程并非 fossilized。')],quiz:[Q('fossilized',1,1,'A fossilized shell is?','preserved as a fossil','newly alive in the sea','made of soft cloth','preserved as a fossil','s1 指已经石化的。'),Q('fossilized',2,2,'A fossilized policy is?','rigid and resistant to change','updated whenever needed','a mineral specimen only','rigid and resistant to change','s2 比喻旧制度僵化。'),Q('fossilized',3,1,'Which sentence uses the literal adjective?','They found a fossilized fern in the rock.','The office has a fossilized meeting schedule.','The rule fossilized into habit.','They found a fossilized fern in the rock.','岩石中保存的蕨类化石体现字面义。'),Q('fossilized',4,2,'A fossilized custom is difficult to?','change','recognize as a custom','write down','change','比喻义强调习俗已僵固、不易改变。')]});
D('foundry',{etymology:E('Foundry came through French fonderie from fondre “to melt,” ultimately Latin fundere “to pour.” It names a workshop where metal is melted and cast.','foundry'),contexts:[C('foundry.s1','金属铸造','The foundry melted recycled bronze, poured it into sand moulds, and left the castings to cool before workers removed them.','铸造厂熔化回收青铜，将其浇入砂模，待铸件冷却后再由工人取出。','The foundry melted recycled bronze / poured it into sand moulds / and left the castings to cool / before workers removed them.','foundry 指熔炼、浇铸金属的车间或工厂。','熔金属入模并冷却铸件是铸造流程。')],mistakes:[M('The foundry made bronze castings by keeping the metal solid and never pouring it into a mould.','The foundry made bronze castings by melting the metal and pouring it into moulds.','不熔化、不浇注就不能按所述方法铸造金属。')],quiz:[Q('foundry',1,1,'A foundry is a place where workers?','melt and cast metal','grow seedlings','print newspapers only','melt and cast metal','foundry 指金属铸造厂。'),Q('foundry',2,1,'A foundry pours molten metal into?','moulds','paper envelopes','river nets','moulds','铸造时将熔融金属浇入模具。'),Q('foundry',3,1,'Which industry uses a foundry?','metal casting','freshwater fishing','film editing','metal casting','铸造厂属于金属加工行业。'),Q('foundry',4,1,'The historical root related to foundry means?','to melt','to sing','to sleep','to melt','foundry 经法语词与“熔化”有关。')]});
D('fourfold',{etymology:E('Fourfold combines four and fold, an old element meaning “times” or “in layers.” It means four times as much or consisting of four parts.','fourfold'),contexts:[C('fourfold.s2','成本增长','After the port closed, shipping costs rose fourfold, so the cooperative postponed the purchase until a cheaper route became available.','港口关闭后，运输成本涨到原来的四倍，因此合作社推迟采购，等待更便宜的路线。','After the port closed / shipping costs rose fourfold / so the cooperative postponed the purchase / until a cheaper route became available.','fourfold 作副词修饰 rose，说明增长为原来的四倍。','成本倍增后推迟采购，体现倍数义 s2。')],mistakes:[M('The bill rose fourfold from $10 to $11, a rise of only ten percent.','The bill rose slightly from $10 to $11, a rise of ten percent.','从10到11只增长十分之一，不是四倍。')],quiz:[Q('fourfold',1,1,'A fourfold increase means the amount becomes?','four times its former level','one quarter of its former level','four units less','four times its former level','fourfold 表示四倍的或四重的。'),Q('fourfold',2,2,'Sales rose fourfold. They?','became four times as high','fell by four percent','stayed exactly unchanged','became four times as high','副词义说明数量增至原来的四倍。'),Q('fourfold',3,1,'A fourfold structure has?','four parts or layers','two parts only','no divisions','four parts or layers','形容词义可指由四部分组成。'),Q('fourfold',4,2,'Which result is a fourfold rise from 5?','20','9','1','20','5 的四倍是20。')]});
D('fractious',{etymology:E('Fractious is recorded in English from the eighteenth century for an irritable or unruly person; its deeper origin is uncertain. It describes bad-tempered, difficult behaviour.','fractious'),contexts:[C('fractious.s1','课堂管理','The fractious pupils interrupted one another throughout the lesson, so the teacher paused the debate and reset the speaking rules.','这些易怒难管的学生整节课互相打断，因此教师暂停辩论并重新说明发言规则。','The fractious pupils interrupted one another throughout the lesson / so the teacher paused the debate / and reset the speaking rules.','fractious 修饰 pupils，表示烦躁易怒、难以管理。','持续打断讨论表现出难管和易怒。')],mistakes:[M('The fractious committee calmly accepted every proposal and waited patiently for each speaker.','The cooperative committee calmly accepted the proposals and waited patiently for each speaker.','平静合作与易怒、难以管理相反。')],quiz:[Q('fractious',1,1,'A fractious child is often?','irritable and difficult to manage','calm and cooperative','too young to speak','irritable and difficult to manage','fractious 描述烦躁易怒、难管。'),Q('fractious',2,1,'A fractious meeting may be marked by?','frequent angry interruptions','quiet agreement on every point','no participants at all','frequent angry interruptions','互相打断和争执体现 fractious。'),Q('fractious',3,1,'Choose the closest meaning.','unruly','placid','obedient','unruly','unruly 与难以管理相近。'),Q('fractious',4,1,'The chair tried to calm the fractious group by?','setting clear turn-taking rules','encouraging everyone to shout at once','cancelling all communication permanently','setting clear turn-taking rules','易怒群体需要规则来减少冲突。')]});
D('fragility',{etymology:E('Fragility comes from French fragilité and Latin fragilitas, from fragilis “liable to break,” related to frangere “to break.” It is the quality of being easily damaged or vulnerable.','fragility'),contexts:[C('fragility.s1','古物运输','Because of the vase’s fragility, conservators packed it in a fitted foam case and limited handling during the journey.','由于花瓶易碎，文物修复人员将它装入定制泡沫箱，并在运输途中尽量减少搬动。','Because of the vase’s fragility / conservators packed it in a fitted foam case / and limited handling during the journey.','fragility 是不可数抽象名词，表示易碎、脆弱的性质。','易损特性促使工作人员加强保护，体现义项。')],mistakes:[M('The steel case’s fragility meant it could withstand any impact without bending or breaking.','The steel case’s strength meant it could withstand impact without bending or breaking.','耐冲击与 fragility（易碎性）相反。')],quiz:[Q('fragility',1,1,'Fragility is the quality of being?','easily broken or damaged','impossible to bend','very loud','easily broken or damaged','fragility 表示易碎或脆弱。'),Q('fragility',2,1,'A museum protects a fragile vase because of its?','fragility','fraternity','frenzy','fragility','花瓶易损的性质是其 fragility。'),Q('fragility',3,1,'Which word is closest to fragility?','brittleness','durability','strength','brittleness','brittleness 表示易碎性。'),Q('fragility',4,1,'A system’s fragility may be revealed when?','a small disruption causes it to fail','it absorbs every shock easily','it runs reliably under all conditions','a small disruption causes it to fail','脆弱系统经不起小干扰。')]});
D('fragmentary',{etymology:E('Fragmentary is formed from fragment plus -ary. Fragment comes through French from Latin fragmentum, from frangere “to break”; fragmentary describes pieces or incomplete information.','fragmentary'),contexts:[C('fragmentary.s2','历史档案','The account of the fire remained fragmentary because only a few letters and one damaged ledger survived.','由于只留下少量信件和一本受损账簿，这场火灾的记载仍然零散不全。','The account of the fire remained fragmentary / because only a few letters and one damaged ledger survived.','fragmentary 修饰 account，指记载不完整、资料零散。','幸存材料很少，无法形成完整叙述，符合 s2。')],mistakes:[M('The fragmentary archive contained every page, letter, and signed record in perfect order.','The complete archive contained every page, letter, and signed record in perfect order.','资料完整有序与 fragmentary（零散不全）相反。')],quiz:[Q('fragmentary',1,1,'A fragmentary object consists of?','separate broken pieces','one flawless unbroken whole','a liquid mixture','separate broken pieces','s1 指碎片般、由残片构成。'),Q('fragmentary',2,2,'A fragmentary historical account is?','incomplete and based on scattered records','fully documented from every day','a fictional novel by definition','incomplete and based on scattered records','s2 指记载零散、不完整。'),Q('fragmentary',3,2,'Why might an archive be fragmentary?','many original documents have been lost','every record is preserved intact','the archive is newly built','many original documents have been lost','资料散佚会使历史记载不完整。'),Q('fragmentary',4,1,'The adjective fragmentary is related to?','fragments or broken pieces','a complete circle','a strong friendship','fragments or broken pieces','词形和词义都与 fragment（碎片）相关。')]});
D('fragmentation',{etymology:E('Fragmentation is formed from fragment plus -ation. It names the process of breaking into parts or becoming divided into disconnected groups.','fragmentation'),contexts:[C('fragmentation.s1','栖息地保护','Road construction caused habitat fragmentation, separating the forest into small patches that isolated several animal populations.','道路建设造成栖息地碎片化，把森林分割成小块，使数个动物种群彼此隔离。','Road construction caused habitat fragmentation / separating the forest into small patches / that isolated several animal populations.','fragmentation 是过程名词，指整体被分割成彼此分离的部分。','森林被道路切成零散小块，符合生态学义。')],mistakes:[M('The new corridor reduced habitat fragmentation by splitting the forest into more isolated patches.','The new corridor reduced habitat fragmentation by reconnecting the separated forest patches.','进一步切割会加剧而非减少碎片化。')],quiz:[Q('fragmentation',1,1,'Habitat fragmentation occurs when?','a continuous habitat is split into isolated patches','a forest becomes one unbroken area','animals all move into one nest','a continuous habitat is split into isolated patches','fragmentation 指生境被分割成碎片。'),Q('fragmentation',2,1,'Political fragmentation can produce?','many separate competing groups','one united party only','a single shared opinion','many separate competing groups','该词也可表示群体分裂。'),Q('fragmentation',3,1,'A wildlife corridor may reduce?','habitat fragmentation','fossilization','freshness','habitat fragmentation','廊道重新连接生境，可减少碎片化。'),Q('fragmentation',4,1,'Fragmentation is the process of?','breaking or dividing into parts','joining every piece into one','measuring the whole','breaking or dividing into parts','词义核心是分裂、碎片化。')]});
D('fragmented',{etymology:E('Fragmented is the past participle and adjective from fragment, ultimately Latin fragmentum “a broken piece.” It describes something divided into disconnected parts.','fragmented'),contexts:[C('fragmented.s1','公共服务','Residents faced a fragmented health service, with separate agencies keeping incompatible records and sending them between offices.','居民面对的是分散割裂的医疗服务：不同机构各自保存不兼容的记录，并让他们在办公室之间奔波。','Residents faced a fragmented health service / with separate agencies keeping incompatible records / and sending them between offices.','fragmented 修饰 service，表示系统被分割、不连贯。','机构各自为政、记录无法共享，体现碎片化服务。')],mistakes:[M('The fragmented service used one shared record system and coordinated every agency through a single team.','The integrated service used one shared record system and coordinated every agency through a single team.','共享记录、统一协调体现整合，不是 fragmented。')],quiz:[Q('fragmented',1,1,'A fragmented service is?','divided into disconnected parts','fully coordinated as one system','made of one solid material','divided into disconnected parts','fragmented 表示分散割裂。'),Q('fragmented',2,1,'A fragmented conversation may be?','broken into disjointed pieces','smooth and continuous','a formal contract','broken into disjointed pieces','不连贯的片段式谈话符合该词义。'),Q('fragmented',3,1,'Which is a fragmented record system?','agencies keep incompatible separate files','all offices use one shared database','one clerk updates a common record','agencies keep incompatible separate files','互不兼容的分散记录构成碎片化系统。'),Q('fragmented',4,1,'Fragmented is closest to?','disjointed','unified','seamless','disjointed','disjointed 表示不连贯、割裂。')]});
D('framer',{etymology:E('Framer is formed from frame plus the agent suffix -er. It can name someone who formulates a plan or document, or a craftsperson who fits pictures into frames.','framer'),contexts:[C('framer.s1','宪章起草','The framer of the charter chose broad language so later councils could apply its principles to disputes that had not yet arisen.','宪章的起草者采用宽泛措辞，使后来的委员会能将其原则用于尚未出现的争议。','The framer of the charter chose broad language / so later councils could apply its principles / to disputes that had not yet arisen.','framer 在此指拟定或起草文件的人。','选择宪章措辞和构思原则体现制定者义 s1。')],mistakes:[M('The charter’s framer had no role in drafting it and first read it after publication.','The charter’s reader had no role in drafting it and first saw it after publication.','未参与拟定文件的人不是其 framer。')],quiz:[Q('framer',1,1,'A framer of a constitution helps?','draft or formulate it','repair a bicycle tyre','deliver a parcel','draft or formulate it','s1 指构思、制定文件的人。'),Q('framer',2,2,'A picture framer would?','fit artwork into a frame','write a constitution','operate a foundry','fit artwork into a frame','s2 指装框匠。'),Q('framer',3,1,'Which person is a framer of a proposal?','the person who develops its wording and structure','someone who reads it once','the person who prints envelopes','the person who develops its wording and structure','制定方案内容结构的人是 framer。'),Q('framer',4,2,'Choose the craft meaning.','The framer mounted the print behind glass.','The framer proposed a new law.','The framer voted on the bill.','The framer mounted the print behind glass.','装裱版画体现装框匠义。')]});
D('France',{etymology:E('France comes through Old French France from Latin Francia, “land of the Franks.” The country name also appears in cultural and historical contexts referring to the French nation.','France'),contexts:[C('France.s1','地理说明','France borders several European countries and also has coastlines on the Atlantic Ocean and the Mediterranean Sea.','法国与多个欧洲国家接壤，也拥有大西洋和地中海海岸线。','France borders several European countries / and also has coastlines / on the Atlantic Ocean and the Mediterranean Sea.','France 是国家专名，首字母大写。','句中指欧洲国家及其地理范围，符合 s1。')],mistakes:[M('France is a language spoken by millions, while French is the name of the country.','France is the country, while French is its language.','把国家名 France 与语言名 French 对调了。')],quiz:[Q('France',1,1,'France is?','a country in Europe','a language family','a mountain range in Asia','a country in Europe','s1 指法国这个国家。'),Q('France',2,2,'A book about France’s art and history may discuss?','French culture and historical life','only the weather on Mars','the grammar of Japanese','French culture and historical life','s2 指法国的文化、历史语境。'),Q('France',3,1,'Which sentence uses France as a country name?','They travelled across France by train.','They spoke France at home.','The France was translated into Spanish.','They travelled across France by train.','France 是国家名，不是语言名。'),Q('France',4,1,'The people and language associated with France are called?','French','Franceish','Francing','French','French 是法国人/法国的/法语。','word-formation')]});
D('fraternal',{etymology:E('Fraternal comes from Latin fraternalis, from frater “brother.” It describes a brother or brotherly relationship, including warmth and solidarity between people.','fraternal'),contexts:[C('fraternal.s1','互助关系','The two volunteers formed a fraternal bond while rebuilding the village school, sharing tools and checking on each other after long shifts.','两名志愿者在重建乡村学校时结下了兄弟般的情谊，彼此分享工具，并在长时间工作后互相照应。','The two volunteers formed a fraternal bond / while rebuilding the village school / sharing tools / and checking on each other after long shifts.','fraternal 修饰 bond，表示兄弟般的亲密、团结。','互助和关怀体现像兄弟一样的关系。')],mistakes:[M('Their fraternal relationship was hostile and competitive, with each person refusing to help the other.','Their relationship was hostile and competitive, with each person refusing to help the other.','敌对竞争且拒绝互助不体现兄弟般情谊。')],quiz:[Q('fraternal',1,1,'A fraternal bond suggests?','brotherly affection or solidarity','a business invoice','a cold laboratory result','brotherly affection or solidarity','fraternal 源自 brother，表示兄弟般的情谊。'),Q('fraternal',2,1,'Which action is fraternal?','volunteers supporting one another like brothers','colleagues sabotaging each other','strangers ignoring a shared emergency','volunteers supporting one another like brothers','彼此扶持体现兄弟般团结。'),Q('fraternal',3,1,'Fraternal is related to the Latin word for?','brother','river','stone','brother','词源 frater 意为兄弟。'),Q('fraternal',4,1,'Choose the natural phrase.','fraternal affection','fraternal rainfall','fraternal motor oil','fraternal affection','fraternal affection 表示兄弟般情谊。')]});
// NEXT CHECKPOINT
D('fraternity',{etymology:E('Fraternity came through French from Latin fraternitas, based on frater “brother.” It can mean brotherhood or a professional group, and also a male student society at some North American universities.','fraternity'),contexts:[C('fraternity.s2','校园社团','The fraternity organized a winter coat drive, but the university required it to publish its finances and follow the same safety rules as other student groups.','这个大学兄弟会组织了冬衣募捐，但校方要求它公开财务，并遵守与其他学生团体相同的安全规定。','The fraternity organized a winter coat drive / but the university required it / to publish its finances / and follow the same safety rules as other student groups.','北美大学语境中的 fraternity 是男性学生社团。','社团活动和大学规章语境对应义项 s2。')],mistakes:[M('The fraternity was a university student society with no student members and no organized activities.','The fraternity was a university student society with student members and organized activities.','没有成员、也无组织活动的团体不符合大学社团含义。')],quiz:[Q('fraternity',1,1,'Fraternity can refer to?','brotherhood or a group sharing an occupation','a refrigerated cabinet','a type of mural','brotherhood or a group sharing an occupation','s1 指兄弟情谊或同业团体。'),Q('fraternity',2,2,'On a North American campus, a fraternity is often?','a male student society','a language department','a kind of dormitory appliance','a male student society','s2 指大学兄弟会。'),Q('fraternity',3,1,'A professional fraternity may unite people who share?','a field of work','a refrigerator model','a country’s coastline','a field of work','同业团体因共同职业或信念形成。'),Q('fraternity',4,2,'Which activity could a campus fraternity organize?','a student charity drive','a national census office','a ship’s cargo route','a student charity drive','大学社团可以组织学生公益活动。')]});
D('fraudulent',{etymology:E('Fraudulent combines fraud with -ulent, an adjective-forming ending. Fraud comes from Latin fraus “deception.” Fraudulent describes an act intended to cheat or deceive.','fraudulent'),contexts:[C('fraudulent.s1','金融审查','The bank froze the payment after its review found a fraudulent invoice for equipment that the supplier had never delivered.','银行发现这张设备发票涉及供应商从未交付的货物，因而冻结了付款。','The bank froze the payment / after its review found a fraudulent invoice / for equipment that the supplier had never delivered.','fraudulent 修饰 invoice，表示发票用于欺骗、骗取款项。','收费项目并未交付却开票索款，符合欺诈义。')],mistakes:[M('The auditor called the invoice fraudulent even though it accurately listed goods delivered and matched the signed receipt.','The auditor called the invoice legitimate because it accurately listed delivered goods and matched the receipt.','真实交付且记录吻合，不构成此处的欺诈发票。')],quiz:[Q('fraudulent',1,1,'A fraudulent claim is made?','to deceive or cheat','to report a verified fact','to ask a neutral question','to deceive or cheat','s1 指为骗取钱财而做的欺诈行为。'),Q('fraudulent',2,2,'A fraudulent person is?','dishonest and intending to deceive','honest and transparent','merely unfamiliar with a form','dishonest and intending to deceive','s2 描述意图欺骗的不诚实的人或行为。'),Q('fraudulent',3,1,'Which transaction is fraudulent?','billing for equipment never supplied','paying for goods that arrived','correcting a harmless typing error','billing for equipment never supplied','虚报未交付设备以骗钱，属于欺诈。'),Q('fraudulent',4,2,'Fraudulent differs from mistaken because it involves?','dishonest intent to deceive','an accidental spelling slip','a slow delivery caused by weather','dishonest intent to deceive','欺诈性行为含有不诚实的欺骗意图。')]});
D('fraught',{etymology:E('Fraught is the past participle of an older form related to freight, originally suggesting a ship loaded with cargo. It developed the sense “filled with” and often describes danger, tension, or worry.','fraught'),contexts:[C('fraught.s2','敏感会谈','The discussion was fraught with tension because both families feared that one careless remark could reopen the dispute.','这场讨论充满紧张气氛，因为两家人都担心一句不慎的话会重新引发争端。','The discussion was fraught with tension / because both families feared / that one careless remark could reopen the dispute.','常见结构为 be fraught with + 名词。','对话带来焦虑、紧张，符合 s2。')],mistakes:[M('The meeting was fraught with worry, and every participant felt completely relaxed and carefree.','The meeting was free of worry, and every participant felt relaxed and carefree.','充满担忧与完全轻松无忧矛盾。')],quiz:[Q('fraught',1,1,'A route fraught with danger is?','full of danger','free from all risk','paved with soft cloth','full of danger','s1 表示充满危险或问题。'),Q('fraught',2,2,'A fraught conversation is likely to cause?','worry or tension','complete indifference','a musical performance','worry or tension','s2 描述令人紧张、担忧的情境。'),Q('fraught',3,1,'Choose the usual construction.','fraught with problems','fraught of problems','fraught for problemly','fraught with problems','常用 fraught with。'),Q('fraught',4,2,'If a decision is fraught, people may feel?','anxious about its consequences','certain it has no consequences','hungry for lunch','anxious about its consequences','该词可表示令人焦虑紧张。')]});
D('freak',{etymology:E('Freak has been used in English since the sixteenth century for a whim or unusually strange event; its deeper origin is uncertain. It can name an abnormal person, animal, or occurrence, and also modify “very unusual.”','freak'),contexts:[C('freak.s2','异常天气','A freak hailstorm struck the coastal town in midsummer, damaging roofs before the unusually intense cloud passed.','盛夏时一场反常的冰雹袭击沿海小镇，在异常强烈的云团移过前损坏了屋顶。','A freak hailstorm struck the coastal town in midsummer / damaging roofs / before the unusually intense cloud passed.','freak 在此作定语，表示极不寻常、出乎意料。','盛夏突发的异常冰雹天气符合 s2。')],mistakes:[M('The weather service called the daily, predictable sunrise a freak event that had never been observed before.','The weather service called the rare, unexpected hailstorm a freak event.','每天可预测的日出并非反常、罕见事件。')],quiz:[Q('freak',1,1,'A freak of nature may be?','an extremely abnormal occurrence','an ordinary event that happens daily','a legal document','an extremely abnormal occurrence','s1 可指反常的人、物或事件。'),Q('freak',2,2,'A freak storm is?','very unusual and unexpected','scheduled every afternoon','mild and completely ordinary','very unusual and unexpected','s2 作定语修饰罕见意外的事。'),Q('freak',3,1,'Which event is most plausibly a freak?','snowfall in a tropical town in midsummer','a normal sunrise','a weekly market opening','snowfall in a tropical town in midsummer','反常季节、地点的降雪属于异常事件。'),Q('freak',4,2,'In “a freak accident,” freak means?','highly unusual','carefully planned','harmless by definition','highly unusual','freak accident 指极不寻常的事故。')]});
D('freelance',{etymology:E('Freelance combines free and lance. Walter Scott used “free lance” for a mercenary not pledged to one lord; the modern word describes independent work for different clients.','freelance'),contexts:[C('freelance.s1','独立摄影','As a freelance photographer, Lena takes assignments from several magazines and chooses her own working schedule between commissions.','莉娜是一名自由摄影师，为多家杂志接单，并在项目之间自行安排工作时间。','As a freelance photographer / Lena takes assignments from several magazines / and chooses her own working schedule / between commissions.','freelance 在此作名词，修饰 photographer，表示不固定受雇于一家单位。','她为不同客户接项目且自行安排工作，符合自由职业者义 s1。')],mistakes:[M('The freelance writer was a permanent employee whose only client was one company under a fixed long-term contract.','The staff writer was a permanent employee working for one company under a fixed long-term contract.','长期固定受雇于单一雇主与 freelance 的独立接单模式不符。')],quiz:[Q('freelance',1,1,'A freelance designer typically?','works independently for different clients','holds one permanent post at one employer only','works without producing any service','works independently for different clients','s1 指为不同客户接活的自由职业者。'),Q('freelance',2,2,'A freelance assignment is?','work done by an independent worker','a permanent company office','a student fraternity','work done by an independent worker','s2 作形容词指自由职业者承接的工作。'),Q('freelance',3,1,'Which person is freelance?','an editor taking paid projects from several publishers','a staff editor with one permanent employer','a reader buying a magazine','an editor taking paid projects from several publishers','为多家出版社接项目体现独立接单。'),Q('freelance',4,2,'Choose the natural phrase.','freelance journalist','freelancefully journalist','journalist of freelances','freelance journalist','freelance 可作前置定语修饰职业。')]});
D('freely',{etymology:E('Freely is formed from free plus -ly. Free comes from Old English frēo, “not in bondage”; freely means without control, obstruction, or a charge.','freely'),contexts:[C('freely.s1','表达意见','At the public forum, residents could speak freely without submitting their comments for approval in advance.','在公众论坛上，居民可以自由发言，无须事先提交意见供审批。','At the public forum / residents could speak freely / without submitting their comments / for approval in advance.','freely 修饰 speak，表示不受限制地表达。','无需预先审批体现表达不受控制。')],mistakes:[M('The residents spoke freely, but every sentence had to be approved by officials before anyone could say it.','The residents could not speak freely because officials had to approve every sentence in advance.','逐句预审限制表达，与 freely 相矛盾。')],quiz:[Q('freely',1,1,'To speak freely is to speak?','without being controlled or blocked','only after paying a fee','in a whisper no one can hear','without being controlled or blocked','freely 表示不受限制地。'),Q('freely',2,1,'If information circulates freely, it?','moves without obstruction','is kept under total secrecy','must be purchased each time','moves without obstruction','freely 可表示不受阻碍地传播。'),Q('freely',3,1,'Which phrase is natural?','move freely through the room','freely move of roomly','freefully moves in room','move freely through the room','副词 freely 修饰 move。'),Q('freely',4,1,'A service offered freely is?','available without charge','locked behind a fee','impossible to use','available without charge','freely 也可指免费地提供。')]});
D('freeware',{etymology:E('Freeware combines free and software. The modern computer term names software that users can use without paying a fee, though its licence may still limit copying or modification.','freeware'),contexts:[C('freeware.s1','软件许可','The school installed freeware for reading PDFs, but its administrator checked the licence before copying it to every classroom computer.','学校安装了免费 PDF 阅读软件，但管理员在复制到每台教室电脑前先核查了许可证。','The school installed freeware for reading PDFs / but its administrator checked the licence / before copying it / to every classroom computer.','freeware 指可免费使用的软件；免费不等同于无版权或可任意修改。','软件免费使用且仍须遵守许可，符合定义。')],mistakes:[M('The school called the program freeware because it charged every student a monthly fee to open a PDF.','The school called the program paid software because it charged every student a monthly fee.','必须付费才能使用的软件不是 freeware。')],quiz:[Q('freeware',1,1,'Freeware is software users can?','use without paying a fee','use only after buying a licence key','run only without a computer','use without paying a fee','freeware 的关键是无需付费使用。'),Q('freeware',2,1,'Does freeware automatically mean users may modify its code?','No; the licence can still restrict modification.','Yes; the word guarantees unrestricted source access.','No; it cannot be installed anywhere.','No; the licence can still restrict modification.','免费使用不自动等于开放源码或无限授权。'),Q('freeware',3,1,'Which is freeware?','a program distributed for use at no charge','an app that requires a monthly subscription','a paper manual sold in a shop','a program distributed for use at no charge','免费分发的软件符合 freeware。'),Q('freeware',4,1,'The word freeware combines free and?','software','firewood','French','software','该术语由 free 与 software 构成。')]});
D('freighter',{etymology:E('Freighter is formed from freight plus -er. Freight came through French from a word for loading cargo; a freighter can be a cargo ship or a person or company that transports goods.','freighter'),contexts:[C('freighter.s1','海上运输','The freighter left the harbour at dawn carrying grain and machinery to three ports along the coast.','这艘货船黎明时离港，载着谷物和机械前往沿海的三个港口。','The freighter left the harbour at dawn / carrying grain and machinery / to three ports along the coast.','freighter 的 s1 指运载货物的大型船只。','船舶装载谷物和机械前往港口，符合货船义。')],mistakes:[M('The freighter crossed the ocean carrying no cargo and was built only to transport passengers.','The passenger liner crossed the ocean carrying passengers rather than cargo.','专运乘客而非货物的船不符合此处 freighter。')],quiz:[Q('freighter',1,1,'A sea freighter is a ship built to carry?','goods and cargo','only tourists on a cruise','fresh water in a glass','goods and cargo','s1 指海上货船。'),Q('freighter',2,2,'A freighter in the transport business may be?','a company moving goods for clients','a mural painter','a student society','a company moving goods for clients','s2 指货运承运人或公司。'),Q('freighter',3,1,'Which load suits a freighter?','containers of machinery','a single postage stamp','an empty bookshelf only','containers of machinery','货船可运送机械等大型货物。'),Q('freighter',4,1,'A ship is called a freighter because it?','carries freight','carries only musical instruments','creates fossils','carries freight','freighter 由 freight 派生，表示载货。')]});
D('French',{etymology:E('French comes from Old English Frencisc, “of the Franks,” related to Francia and the Frankish people. It names the language, people, or things associated with France.','French'),contexts:[C('French.s1','语言学习','The guide spoke French with the visitors and then translated the museum’s safety instructions into English for the rest of the group.','导游用法语与访客交谈，随后又为团内其他人把博物馆安全说明译成英语。','The guide spoke French with the visitors / and then translated the museum’s safety instructions / into English / for the rest of the group.','French 作语言名时首字母大写。','与 English 对照的 spoken language 体现 s1。')],mistakes:[M('She learned French, the language spoken in France, but wrote its name with a lowercase initial in the sentence.','She learned French, the language spoken in France, and capitalized its name.','语言专名 French 首字母需大写。','capitalization')],quiz:[Q('French',1,1,'French is a language spoken in?','France and other countries','France only as a type of currency','the Arctic Ocean only','France and other countries','s1 指法语，许多国家也使用。'),Q('French',2,2,'The French as a group means?','the people of France','only the French language','a type of ship','the people of France','the French 可指法国人民。'),Q('French',3,3,'French cuisine means cuisine?','associated with France','invented in Finland','made only from fresh water','associated with France','s3 表示与法国有关的。'),Q('French',4,1,'Which spelling is correct for the language name?','French','french','Frenche','French','语言专名 French 要大写。','capitalization')]});
D('frenetic',{etymology:E('Frenetic came through Latin from Greek phrenetikos, “delirious,” related to phren “mind.” It describes extremely hurried, confused activity or wild excitement.','frenetic'),contexts:[C('frenetic.s1','急诊调度','The emergency room entered a frenetic period after the storm, with staff moving rapidly between incoming patients and damaged equipment.','暴风雨后急诊室进入忙乱时段，医护人员在新到患者和受损设备之间快速奔走。','The emergency room entered a frenetic period after the storm / with staff moving rapidly / between incoming patients and damaged equipment.','frenetic 修饰 period，描述急速、混乱的活动状态。','人员忙乱穿梭、事务骤增，符合 s1。')],mistakes:[M('The frenetic control room remained silent and idle, with no calls, movement, or urgent work.','The quiet control room remained idle, with no calls, movement, or urgent work.','安静闲置与 frenetic 的忙乱急促相反。')],quiz:[Q('frenetic',1,1,'A frenetic afternoon at work is?','extremely busy and hurried','calm with nothing to do','a formal holiday','extremely busy and hurried','s1 表示忙乱、急促。'),Q('frenetic',2,2,'A frenetic fan may be?','wildly excited and uncontrolled','calmly indifferent','asleep throughout the event','wildly excited and uncontrolled','s2 指狂热激动、难以控制。'),Q('frenetic',3,1,'Which scene is frenetic?','staff rushing between alarms and calls','a quiet room with no tasks','a slow walk in a garden','staff rushing between alarms and calls','快速而混乱的活动符合 frenetic。'),Q('frenetic',4,1,'Choose the natural collocation.','frenetic activity','frenetic stillness for years','frenetically table','frenetic activity','frenetic 常修饰 activity。')]});
D('fresco',{etymology:E('Fresco came from Italian fresco “fresh,” referring to paint applied to fresh wet plaster. It is a wall painting made by that technique and can also be used as a verb.','fresco'),contexts:[C('fresco.s1','壁画修复','The conservator dampened the wall carefully before examining the fresco, whose pigments had bonded with the plaster as it dried.','修复人员仔细润湿墙面后检查湿壁画；颜料在墙灰干燥时与灰泥结合。','The conservator dampened the wall carefully / before examining the fresco / whose pigments had bonded with the plaster / as it dried.','fresco 作名词指在新铺湿灰泥上绘制的壁画。','颜料与灰泥在干燥时结合是湿壁画技法特征。')],mistakes:[M('The museum labelled a loose oil painting on canvas a fresco even though it had never been painted on wet plaster.','The museum labelled the wall painting made on wet plaster a fresco.','布面油画并非湿壁画技法。')],quiz:[Q('fresco',1,1,'A fresco is painted on?','fresh wet plaster','a dry sheet of glass','a ship’s flagpole','fresh wet plaster','湿壁画在新铺湿灰泥上作画。'),Q('fresco',2,2,'To fresco a wall is to?','decorate it with fresco painting','install a refrigerator','load it with cargo','decorate it with fresco painting','s2 作动词表示绘制湿壁画。'),Q('fresco',3,1,'Why does fresco paint bond with the wall?','the pigment is applied while plaster is wet','the canvas is removed before painting','the wall is made of cloth','the pigment is applied while plaster is wet','湿灰泥干燥时颜料融入表面。'),Q('fresco',4,1,'The Italian word behind fresco means?','fresh','frozen','fourfold','fresh','fresco 源自意大利语“新鲜的”。')]});
D('freshly',{etymology:E('Freshly is formed from fresh plus -ly. Fresh comes from Old English fersc; the adverb often means only a short time ago or in a recently made state.','freshly'),contexts:[C('freshly.s1','餐食准备','The chef served freshly baked bread while it was still warm, setting the loaves beside the soup rather than reheating yesterday’s leftovers.','厨师端上刚烤好的面包，趁它还温热时与汤一起上桌，而不是重新加热昨天的剩饭。','The chef served freshly baked bread / while it was still warm / setting the loaves beside the soup / rather than reheating yesterday’s leftovers.','freshly 修饰 baked，表示不久前刚烤好。','面包刚出炉仍温热，符合新近地、刚刚义。')],mistakes:[M('The bakery described bread kept on the shelf for six weeks as freshly baked.','The bakery described bread taken from the oven a few minutes ago as freshly baked.','存放六周的面包并非刚刚烤制。')],quiz:[Q('freshly',1,1,'Freshly painted walls were painted?','only a short time ago','many years earlier','without any paint','only a short time ago','freshly 表示刚刚、新近。'),Q('freshly',2,1,'Which item is freshly made?','bread taken from the oven minutes ago','bread left uncovered for months','an empty basket','bread taken from the oven minutes ago','刚出炉的面包是新近做好的。'),Q('freshly',3,1,'Choose the natural phrase.','freshly picked flowers','freshly pick flowers yesterday','freshly flowers pickedly','freshly picked flowers','freshly 修饰过去分词 picked。','grammar'),Q('freshly',4,1,'Freshly can modify a past participle such as?','painted','paint','paints','painted','副词可修饰过去分词，如 freshly painted。','grammar')]});
D('freshness',{etymology:E('Freshness is formed from fresh plus the noun suffix -ness. It names the state of being newly made, cool, clean, or original.','freshness'),contexts:[C('freshness.s1','蔬果储存','The grocer checked the freshness of the herbs by smelling them and looking for firm leaves rather than wilted, brown edges.','杂货商通过闻香气并查看叶片是否挺实、边缘是否未枯褐来判断香草的新鲜度。','The grocer checked the freshness of the herbs / by smelling them / and looking for firm leaves / rather than wilted, brown edges.','freshness 是抽象名词，表示新鲜状态。','挺实的叶片和新鲜气味用于判断食材新鲜度。')],mistakes:[M('The herbs had been wilted and mouldy for weeks, yet the grocer praised their freshness.','The herbs had been wilted and mouldy for weeks, so the grocer doubted their freshness.','萎蔫发霉与新鲜状态相反。')],quiz:[Q('freshness',1,1,'Freshness in food refers to being?','newly prepared or still in good condition','stored until spoiled','made from metal','newly prepared or still in good condition','freshness 指食物新鲜的状态。'),Q('freshness',2,1,'A reviewer may praise the freshness of an idea because it is?','original and new','copied without change','impossible to understand','original and new','freshness 也可比喻创意新颖。'),Q('freshness',3,1,'Which suffix forms the noun freshness?','-ness','-ly','-ment','-ness','fresh + -ness 构成名词。','word-formation'),Q('freshness',4,1,'Choose the natural phrase.','the freshness of the fruit','the freshful of fruit','freshnessly fruit','the freshness of the fruit','freshness 可与 of 连用说明新鲜度。','grammar')]});
D('freshwater',{etymology:E('Freshwater combines fresh and water. It describes water that is not salty, and organisms or habitats in rivers and lakes rather than the sea.','freshwater'),contexts:[C('freshwater.s1','生态调查','The researchers sampled freshwater fish from the lake, measuring oxygen levels at several depths before releasing each specimen.','研究人员从湖中采集淡水鱼样本，在放归前测量多个深度的含氧量。','The researchers sampled freshwater fish from the lake / measuring oxygen levels at several depths / before releasing each specimen.','freshwater 作定语修饰 fish，表示生活于淡水中。','湖泊而非海洋中的鱼属于淡水生物。')],mistakes:[M('The biologist classified a fish living in salty ocean water as freshwater.','The biologist classified a fish living in salty ocean water as marine.','海水生物与 freshwater（淡水的）相反。')],quiz:[Q('freshwater',1,1,'Freshwater is water that?','contains little or no salt','is always frozen','comes only from a bottle','contains little or no salt','freshwater 指淡水，与咸水相对。'),Q('freshwater',2,1,'A freshwater fish usually lives in?','a river or lake','the open salty sea','a dry desert','a river or lake','河流和湖泊是常见淡水栖息地。'),Q('freshwater',3,1,'Choose the natural phrase.','freshwater habitat','fresh waterly habitat','freshwater of fish only','freshwater habitat','freshwater 可作定语修饰 habitat。','grammar'),Q('freshwater',4,1,'Freshwater contrasts with?','salt water','fresh bread','cold air','salt water','淡水的含盐量低，与海水相对。')]});
D('fridge',{etymology:E('Fridge is a shortened form of refrigerator. Refrigerator derives from Latin refrigerare “to make cool,” from re- and frigus “cold.”','fridge'),contexts:[C('fridge.s1','厨房储存','Put the milk back in the fridge after breakfast so it stays cold until the children return from school.','早餐后把牛奶放回冰箱，这样孩子们放学回来时牛奶仍是冷的。','Put the milk back in the fridge after breakfast / so it stays cold / until the children return from school.','fridge 是 refrigerator 的非正式缩略说法。','电器用来保持牛奶低温，符合定义。')],mistakes:[M('She put the milk in the oven to keep it cold until lunch.','She put the milk in the fridge to keep it cold until lunch.','烤箱加热食物，冰箱才用于冷藏。')],quiz:[Q('fridge',1,1,'A fridge is an appliance that?','keeps food cold','heats food with a flame','prints labels','keeps food cold','fridge 指冷藏食品的电器。'),Q('fridge',2,1,'The word fridge is short for?','refrigerator','foundry','freshwater','refrigerator','fridge 是 refrigerator 的缩略词。'),Q('fridge',3,1,'Where should milk be stored to stay cold?','in the fridge','on a hot stove','inside a paper envelope','in the fridge','冰箱可保持牛奶低温。'),Q('fridge',4,1,'Choose the natural phrase.','put the leftovers in the fridge','fry the leftovers in the fridge','fridge the leftovers to a ship','put the leftovers in the fridge','常说 put food in the fridge。')]});
D('friendliness',{etymology:E('Friendliness is formed from friendly plus -ness; friendly is based on friend, from Old English frēond “friend.” It names a warm and welcoming manner.','friendliness'),contexts:[C('friendliness.s1','公共服务','Visitors remembered the librarian’s friendliness because she greeted newcomers warmly and helped them find materials without making them feel rushed.','访客记得图书管理员的亲切，因为她热情问候新人、帮助找资料，也不让人觉得匆忙。','Visitors remembered the librarian’s friendliness / because she greeted newcomers warmly / and helped them find materials / without making them feel rushed.','friendliness 是抽象名词，指友好亲切的品质。','热情接待和耐心协助体现亲切态度。')],mistakes:[M('The receptionist’s friendliness was clear because she ignored every visitor and refused to answer questions.','The receptionist’s unfriendly manner was clear because she ignored visitors and refused to answer questions.','冷漠拒绝与 friendliness 的友好品质相反。')],quiz:[Q('friendliness',1,1,'Friendliness is the quality of being?','warm and welcoming','angry and hostile','cold and unresponsive','warm and welcoming','friendliness 表示友好、亲切。'),Q('friendliness',2,1,'Which action shows friendliness?','welcoming a newcomer and offering help','ignoring a person who asks for directions','shouting at every visitor','welcoming a newcomer and offering help','主动欢迎和帮助他人体现友好。'),Q('friendliness',3,1,'Which suffix forms friendliness?','-ness','-ful','-ize','-ness','friendly + -ness 构成品质名词。','word-formation'),Q('friendliness',4,1,'A friendly receptionist is likely to show?','friendliness','frigidness only','fossilization','friendliness','友好待客体现 friendliness。')]});
D('friendship',{etymology:E('Friendship combines friend and the Old English suffix -scipe, which formed nouns for a state or relationship. It names being friends or a particular friendly relationship.','friendship'),contexts:[C('friendship.s1','长期互助','Their friendship survived years apart because they kept writing, celebrating one another’s successes, and offering support during difficult periods.','他们的友谊经受住了多年分离，因为他们持续通信、为彼此的成功庆祝，并在艰难时期互相支持。','Their friendship survived years apart / because they kept writing / celebrating one another’s successes / and offering support during difficult periods.','friendship 是两人之间的友谊或朋友关系。','长期联系和相互支持体现友谊。')],mistakes:[M('Their friendship grew stronger as both people stopped communicating and refused to help one another.','Their relationship weakened as both people stopped communicating and refused to help one another.','停止联系、拒绝互助与友谊加深矛盾。')],quiz:[Q('friendship',1,1,'Friendship is?','a friendly relationship between people','a kind of refrigerated appliance','a professional mural','a friendly relationship between people','friendship 指朋友关系或友谊。'),Q('friendship',2,1,'Which action can strengthen a friendship?','supporting one another through difficulty','deliberately breaking every promise','refusing all communication','supporting one another through difficulty','互相支持有助于维系友谊。'),Q('friendship',3,1,'The suffix -ship in friendship refers to?','a state or relationship','a ship that carries freight','a past tense','a state or relationship','-ship 可构成表示关系或状态的名词。','word-formation'),Q('friendship',4,1,'Choose the natural phrase.','a close friendship','a friendship of cold machine','friendshiply person','a close friendship','close friendship 是自然搭配。')]});
D('frigid',{etymology:E('Frigid comes from Latin frigidus “cold,” from frigus “cold.” It describes extremely low temperature and, figuratively, an unfriendly or emotionally distant manner.','frigid'),contexts:[C('frigid.s2','人际互动','The manager’s frigid response discouraged the new employee; she answered the greeting without looking up and ended the conversation at once.','经理冷若冰霜的回应让新员工很受挫；她头也不抬地回应问候，随即结束谈话。','The manager’s frigid response discouraged the new employee / she answered the greeting without looking up / and ended the conversation at once.','frigid 在此比喻态度冷淡、不友好。','回避目光并立刻结束谈话体现人际冷漠义 s2。')],mistakes:[M('The host gave a frigid welcome by warmly greeting every guest and offering them tea.','The host gave a warm welcome by greeting every guest and offering tea.','热情接待与 frigid 的冷淡态度相反。')],quiz:[Q('frigid',1,1,'Frigid air is?','extremely cold','warm and humid','mild and sunny','extremely cold','s1 表示严寒的。'),Q('frigid',2,2,'A frigid reply sounds?','unfriendly and emotionally cold','warm and encouraging','loud but cheerful','unfriendly and emotionally cold','s2 比喻人或态度冷淡。'),Q('frigid',3,1,'Which setting is frigid?','a frozen plateau in winter','a tropical greenhouse','a heated kitchen','a frozen plateau in winter','极低温环境符合物理义。'),Q('frigid',4,2,'Which behaviour is frigid?','ignoring a greeting and ending the exchange abruptly','welcoming a guest warmly','offering patient help','ignoring a greeting and ending the exchange abruptly','冷淡无礼的互动符合比喻义。')]});
D('frill',{etymology:E('Frill is recorded in English from the late sixteenth century for a ruffle or gathered edge; its deeper origin is uncertain. Figuratively, it can mean an unnecessary decorative extra.','frill'),contexts:[C('frill.s2','产品设计','The basic version has all the functions customers need, while the premium model adds decorative frills that raise its price but not its usefulness.','基础版已具备顾客所需功能，而高级版增加了装饰性的多余配置，只提高价格却没有增加实用性。','The basic version has all the functions customers need / while the premium model adds decorative frills / that raise its price / but not its usefulness.','frill 在此比喻不必要的额外装饰或配置。','增加价格却不增加实用性，正是多余装饰义 s2。')],mistakes:[M('The designer removed every unnecessary frill to add useless decorative extras to the product.','The designer added unnecessary frills by including useless decorative extras in the product.','去除多余装饰与加入多余装饰前后矛盾。')],quiz:[Q('frill',1,1,'A frill on a sleeve is?','a gathered decorative strip','a cargo ship','a cold storage cabinet','a gathered decorative strip','s1 指褶边装饰。'),Q('frill',2,2,'A product with no frills has?','no unnecessary extras','many decorative additions','no basic functions','no unnecessary extras','s2 指多余的装饰或额外配置。'),Q('frill',3,1,'Which garment detail is a frill?','a ruffled edge on a collar','a flat metal engine','a printed timetable','a ruffled edge on a collar','褶皱边饰是字面义 frill。'),Q('frill',4,2,'Why might a buyer reject frills?','they add cost without useful function','they make the product work better','they reduce the price to zero','they add cost without useful function','多余配置可能涨价却无实用性。')]});
D('frisky',{etymology:E('Frisky is based on frisk, a verb for lively movement; the deeper origin is uncertain. It describes someone or an animal that is energetic and eager to play.','frisky'),contexts:[C('frisky.s1','幼犬行为','After the rain stopped, the frisky puppies raced around the garden, pouncing on leaves and inviting the older dog to play.','雨停后，活泼好动的小狗在花园里来回奔跑，扑向树叶，还邀请年长的狗一起玩。','After the rain stopped / the frisky puppies raced around the garden / pouncing on leaves / and inviting the older dog to play.','frisky 修饰 puppies，表示活跃、爱玩。','奔跑、扑叶并邀请玩耍体现精力充沛的状态。')],mistakes:[M('The frisky puppy lay motionless all day and showed no interest in movement or play.','The lethargic puppy lay motionless all day and showed no interest in play.','整天不动且不爱玩与 frisky 的活泼好动相反。')],quiz:[Q('frisky',1,1,'A frisky puppy is?','lively and eager to play','sick and unable to move','quietly asleep','lively and eager to play','frisky 指活泼、好动、爱玩。'),Q('frisky',2,1,'Which scene is frisky?','a lamb bounding around a field','a tired dog sleeping all day','a statue standing still','a lamb bounding around a field','蹦跳奔跑表现活力。'),Q('frisky',3,1,'Choose the natural phrase.','frisky young animals','friskyly young animals','young animals frisky of','frisky young animals','frisky 可作定语修饰动物。','grammar'),Q('frisky',4,1,'A frisky animal may?','dart about and play','remain motionless from exhaustion','refuse all activity','dart about and play','活泼动物常快速移动、玩耍。')]});
// CHECKPOINT_3
D('fritter',{etymology:E('Fritter as a verb is recorded in the phrase “fritter away”; its deeper history is uncertain. The noun fritter names a small piece of batter fried until crisp.','fritter'),contexts:[C('fritter.s1','时间管理','She frittered away the grant on decorative equipment, leaving too little money to repair the roof before winter.','她把拨款浪费在装饰性设备上，结果剩下的钱不足以在冬天前修屋顶。','She frittered away the grant / on decorative equipment / leaving too little money / to repair the roof before winter.','常用 fritter away + 时间、金钱或精力。','把资金耗在不重要的装饰上，体现浪费义 s1。')],mistakes:[M('The director frittered away the budget by reserving every dollar for essential repairs.','The director carefully saved the budget by reserving every dollar for essential repairs.','全部留作必要维修与挥霍浪费相反。')],quiz:[Q('fritter',1,1,'To fritter away an inheritance is to?','waste it on unimportant things','invest all of it carefully','give it to a charity as planned','waste it on unimportant things','s1 指浪费时间、金钱或精力。'),Q('fritter',2,2,'A fruit fritter is?','a small piece of batter fried crisp','a kind of refrigerator','a fresh fruit salad only','a small piece of batter fried crisp','s2 指油炸面糊小饼，常含水果或肉。'),Q('fritter',3,1,'Choose the natural phrase.','fritter away time','fritter at the money','fritter the hours from','fritter away time','固定搭配 fritter away 表示浪费。','collocation'),Q('fritter',4,2,'Which menu item is a fritter?','banana pieces in crisp fried batter','plain cold milk','a whole uncut apple','banana pieces in crisp fried batter','水果裹面糊油炸可制成 fritter。')]});
D('frivolity',{etymology:E('Frivolity is formed from frivolous plus -ity. Frivolous comes from Latin frivolus “silly, trifling.” The noun can mean unserious behaviour or an unimportant activity.','frivolity'),contexts:[C('frivolity.s2','预算审议','The committee removed several costly frivolities from the renovation plan, keeping the safety upgrades and cutting decorative features with no practical use.','委员会从翻修计划中删掉了几项昂贵而无用的装饰，保留安全升级并削减没有实际用途的美化项目。','The committee removed several costly frivolities / from the renovation plan / keeping the safety upgrades / and cutting decorative features with no practical use.','frivolities 是复数名词，指不重要、无实际用途的东西。','这些装饰昂贵却无实用性，对应 s2。')],mistakes:[M('The committee called the emergency exit and fire alarm frivolities even though both were required for safety.','The committee called the optional gold trim a frivolity because it added no practical value.','安全设施有实际必要性，不是轻浮或无用之物。')],quiz:[Q('frivolity',1,1,'Frivolity in a formal meeting is?','light-hearted behaviour lacking serious purpose','careful emergency planning','a legal requirement','light-hearted behaviour lacking serious purpose','s1 指不严肃、轻浮的行为。'),Q('frivolity',2,2,'An expensive but useless decoration may be a?','frivolity','fraternity','fossil','frivolity','s2 指不足取或无用的小事物。'),Q('frivolity',3,1,'Which action shows frivolity during a serious briefing?','playing with party balloons while safety rules are explained','taking notes on evacuation routes','checking the emergency exits','playing with party balloons while safety rules are explained','严肃说明时玩闹体现轻浮。'),Q('frivolity',4,2,'A buyer cuts frivolities from a budget to remove?','unnecessary extras','essential safety equipment','all planned spending including repairs','unnecessary extras','从预算削去多余而无用的东西。')]});
D('frivolous',{etymology:E('Frivolous comes from Latin frivolus “silly, trifling,” through French. It describes behaviour lacking seriousness or an argument or claim too slight to deserve attention.','frivolous'),contexts:[C('frivolous.s1','法律审查','The judge dismissed the frivolous claim because it offered no evidence and concerned an issue the court had already settled.','法官驳回了这项轻率诉求，因为它没有证据，而且涉及的问题法院早已裁定。','The judge dismissed the frivolous claim / because it offered no evidence / and concerned an issue / the court had already settled.','frivolous 修饰 claim，表示缺乏严肃依据、无足轻重。','没有证据且问题已裁决，诉求缺少实质价值。')],mistakes:[M('The court called the detailed, evidence-based appeal frivolous even though it raised new facts and a serious legal question.','The court called the unsupported repeat appeal frivolous because it raised no new facts or legal question.','有新事实和重要法律问题的上诉并非轻率琐碎。')],quiz:[Q('frivolous',1,1,'A frivolous lawsuit is?','lacking a serious legal basis','supported by decisive new evidence','required by a safety law','lacking a serious legal basis','frivolous 可形容不值得司法审理的诉求。'),Q('frivolous',2,1,'A frivolous remark is?','not serious or important','a carefully researched conclusion','an urgent medical instruction','not serious or important','形容行为或言论时指轻浮、不严肃。'),Q('frivolous',3,1,'Which adjective contrasts with frivolous?','serious','trivial','silly','serious','serious 与 frivolous 的轻率、不严肃相对。'),Q('frivolous',4,1,'A frivolous use of public funds would be?','spending them on pointless luxuries','funding essential repairs','paying an approved emergency bill','spending them on pointless luxuries','无必要的奢侈开支体现不严肃、无价值。')]});
D('front-line',{etymology:E('Front-line combines front and line. It describes the foremost position where fighting occurs or work done in direct contact with the public or an urgent problem.','front-line'),contexts:[C('front-line.s1','医疗服务','Front-line nurses triaged patients at the clinic entrance, while specialist teams waited inside to treat the most serious cases.','一线护士在诊所入口分诊，专科团队则在里面等候救治最严重的病例。','Front-line nurses triaged patients at the clinic entrance / while specialist teams waited inside / to treat the most serious cases.','front-line 作复合形容词，表示直接面向服务对象的一线岗位。','护士在入口直接接诊，符合公共服务一线义。')],mistakes:[M('Front-line staff had no contact with patients and worked only on long-term budget reports in a distant office.','Back-office staff had no contact with patients and worked on budget reports in a distant office.','完全不接触患者的后台工作不属于医疗一线。')],quiz:[Q('front-line',1,1,'Front-line medical staff work?','in direct contact with patients','only in a remote accounting office','without serving any public need','in direct contact with patients','front-line 可指直接面向公众的一线工作。'),Q('front-line',2,1,'In a conflict, the front line is?','the foremost area where fighting happens','the last page of a report','a ship’s funnel','the foremost area where fighting happens','字面义指战斗发生的最前沿。'),Q('front-line',3,1,'Choose the natural phrase.','front-line workers','front linefully workers','workers of forward-line at','front-line workers','连字符复合词可修饰 workers。','grammar'),Q('front-line',4,1,'A front-line teacher is most likely?','working directly with students','designing a distant office’s payroll only','retired from all work','working directly with students','教师直接接触学生，属于教育一线。')]});
D('frontal',{etymology:E('Frontal comes from Latin frontalis, based on frons “forehead, front.” It describes a front-facing direction or something relating to the forehead or frontal lobe.','frontal'),contexts:[C('frontal.s2','医学检查','The scan showed a small injury in the frontal lobe, the front part of the brain involved in planning and voluntary movement.','扫描显示额叶有一处小损伤；额叶位于大脑前部，参与计划和自主运动。','The scan showed a small injury in the frontal lobe / the front part of the brain / involved in planning and voluntary movement.','frontal 在 frontal lobe 中表示与额部/大脑前部有关。','额叶的位置在脑前部，符合 s2。')],mistakes:[M('The neurologist located the frontal lobe at the back of the brain behind the occipital lobe.','The neurologist located the frontal lobe at the front of the brain.','frontal 指前部，与大脑后部位置不符。')],quiz:[Q('frontal',1,1,'A frontal view shows an object?','from the front','from directly underneath only','from its back only','from the front','s1 表示正面的或朝前的。'),Q('frontal',2,2,'The frontal lobe is located near the?','front of the brain','heel of the foot','rear of the knee','front of the brain','s2 指额部或大脑额叶。'),Q('frontal',3,1,'Which phrase uses frontal to mean front-facing?','a frontal photograph of the building','a photograph from behind the building','a side view of its roof','a frontal photograph of the building','正面拍摄体现 s1。'),Q('frontal',4,2,'A frontal headache may be felt near the?','forehead','ankle','lower back','forehead','frontal 与 forehead（额头）相关。')]});
D('frontality',{etymology:E('Frontality is formed from frontal plus -ity. In art history it names a style in which a figure faces the viewer directly, with little bodily twist.','frontality'),contexts:[C('frontality.s1','艺术史分析','The portrait’s frontality makes the ruler stare directly at the viewer, while the shoulders and torso remain almost square to the picture plane.','这幅肖像的正面性使统治者直视观者，同时肩膀和躯干几乎正对画面。','The portrait’s frontality makes the ruler stare directly at the viewer / while the shoulders and torso remain almost square / to the picture plane.','frontality 是艺术风格名词，强调形象正面对观者。','直视观者且身体少有转向，体现正面描绘风格。')],mistakes:[M('The portrait’s frontality comes from the figure turning fully away and hiding the face from the viewer.','The portrait’s frontality comes from the figure facing the viewer directly.','背对观者与正面性正相反。')],quiz:[Q('frontality',1,1,'In art, frontality describes a figure shown?','facing straight outward toward the viewer','with its back fully turned','only as an abstract colour','facing straight outward toward the viewer','frontality 指人物正面朝向观者的风格。'),Q('frontality',2,1,'A portrait with strong frontality usually has?','a direct gaze and little body twist','the subject hidden behind a wall','a view only of the subject’s back','a direct gaze and little body twist','正面性常表现为直视和少转身。'),Q('frontality',3,1,'Frontality is a term most likely used in?','art analysis','weather forecasting','refrigerator repair','art analysis','该词讨论视觉艺术构图风格。'),Q('frontality',4,1,'Which composition has greater frontality?','a figure facing the viewer squarely','a figure shown turning away','an empty landscape with no figure','a figure facing the viewer squarely','人物正面面对观者时正面性强。')]});
D('frosted',{etymology:E('Frosted is formed from frost plus -ed. It can mean covered with frozen moisture or coated with a fine layer of sugar icing.','frosted'),contexts:[C('frosted.s1','玻璃装饰','The bathroom door uses frosted glass, allowing daylight through while blurring the shapes on the other side for privacy.','浴室门使用磨砂玻璃，既能透进日光，又能模糊另一侧的形状以保护隐私。','The bathroom door uses frosted glass / allowing daylight through / while blurring the shapes on the other side / for privacy.','frosted 在此比喻表面像覆霜一样朦胧的玻璃。','表面散射光、模糊影像，符合覆霜般的外观义。')],mistakes:[M('The frosted glass was perfectly transparent, showing every detail on the other side with sharp clarity.','The clear glass was perfectly transparent, showing every detail on the other side.','完全清晰透明与磨砂玻璃的朦胧效果相反。')],quiz:[Q('frosted',1,1,'Frosted glass is usually?','translucent and blurs details','fully transparent like a clear window','made of ice only','translucent and blurs details','磨砂玻璃透光但模糊影像。'),Q('frosted',2,1,'A frosted cake is coated with?','icing or a fine sugar layer','metal filings','freshwater fish','icing or a fine sugar layer','frosted 也可指覆有糖霜的。'),Q('frosted',3,1,'A frosted window may provide?','privacy while letting light through','a perfectly sharp view through it','complete darkness in daylight','privacy while letting light through','磨砂表面遮挡细节并透光。'),Q('frosted',4,1,'Which surface is frosted after a cold night?','one covered with a thin frozen layer','one heated until it melts','one covered in wet paint','one covered with a thin frozen layer','字面义指表面结霜。')]});
D('frowzy',{etymology:E('Frowzy, also spelled frowsy, is recorded in English for an untidy or musty condition; its origin is uncertain. It can describe a dishevelled appearance or a stale smell in an unventilated place.','frowzy'),contexts:[C('frowzy.s2','室内空气','The closed archive had a frowzy smell because damp boxes had been left there for months without fresh air.','档案室长期封闭，潮湿纸箱又放了数月没有通风，因此有一股闷霉味。','The closed archive had a frowzy smell / because damp boxes had been left there for months / without fresh air.','frowzy 修饰 smell，表示闷、不新鲜、有霉味。','潮湿、久闭且不通风造成陈闷气味，符合 s2。')],mistakes:[M('The frowzy room smelled crisp and fresh after months with its windows sealed and damp boxes inside.','The frowzy room smelled stale and musty after months without ventilation.','清新气味与 frowzy 的闷霉味相反。')],quiz:[Q('frowzy',1,1,'A frowzy appearance is?','untidy and unkempt','neatly pressed and polished','brightly coloured','untidy and unkempt','s1 指邋遢、不整洁。'),Q('frowzy',2,2,'A frowzy room smells?','stale or musty','freshly scented','like clean sea air','stale or musty','s2 指不通风造成的闷霉味。'),Q('frowzy',3,1,'Which person might look frowzy?','someone in rumpled, dirty clothes','someone freshly groomed in a clean suit','a painted portrait','someone in rumpled, dirty clothes','衣着凌乱不整体现 s1。'),Q('frowzy',4,2,'Opening a window may help a frowzy room by?','replacing stale air with fresh air','making the room darker forever','adding more damp boxes','replacing stale air with fresh air','通风能改善闷霉、陈旧气味。')]});
D('fructification',{etymology:E('Fructification comes from Latin fructificare “to bear fruit,” formed from fructus “fruit” and facere “make, do.” It names fruit formation or a plant structure that bears spores or seeds.','fructification'),contexts:[C('fructification.s1','植物生长','The botanist recorded fructification in late summer, when the vine began producing fruiting bodies after months of leaf growth.','植物学家记录了夏末的结果过程：藤本植物经过数月长叶后开始形成繁殖体。','The botanist recorded fructification in late summer / when the vine began producing fruiting bodies / after months of leaf growth.','fructification 是植物结果或形成生殖结构的过程。','植株开始形成果实或繁殖体，体现义项。')],mistakes:[M('The study reported fructification before the plant had formed any fruit, spores, seeds, or reproductive structures.','The study reported vegetative growth before the plant formed reproductive structures.','尚未形成果实或生殖结构时，不能报告已经 fructification。')],quiz:[Q('fructification',1,1,'Fructification in a plant refers to?','the formation of fruit or reproductive structures','the loss of all leaves in winter','the cooling of a greenhouse','the formation of fruit or reproductive structures','fructification 指结果或形成生殖结构。'),Q('fructification',2,1,'A botanist studying fructification may examine?','how a plant produces fruits or spores','how a refrigerator chills milk','how a ship carries freight','how a plant produces fruits or spores','该过程涉及植物产生果实或孢子。'),Q('fructification',3,1,'Which Latin idea contributes to fructification?','fruit-bearing','ice melting','stone carving','fruit-bearing','词源包含 fructus“果实”和 facere“做、形成”。'),Q('fructification',4,1,'Fructification is most closely related to?','reproduction in plants','human handwriting','metal casting','reproduction in plants','果实或孢子形成属于植物繁殖。')]});
D('frugal',{etymology:E('Frugal comes from Latin frugalis, related to frux “fruit, produce” and the idea of usefulness or economy. It describes careful spending or, of a meal, simplicity.','frugal'),contexts:[C('frugal.s1','家庭预算','The family lived frugally for a year, repairing appliances and planning meals so they could save enough for a deposit.','这家人节俭生活了一年，通过维修电器和规划膳食，终于攒够了首付款。','The family lived frugally for a year / repairing appliances and planning meals / so they could save enough for a deposit.','frugal 的副词形式 frugally 修饰 lived，表示节俭地生活。','控制开支、维修而非随意购买体现节俭。')],mistakes:[M('The frugal household bought every expensive gadget on impulse and discarded appliances that still worked.','The extravagant household bought expensive gadgets on impulse and discarded working appliances.','冲动消费和浪费与 frugal 的节俭相反。')],quiz:[Q('frugal',1,1,'A frugal shopper tries to?','spend carefully and avoid waste','buy every item regardless of cost','throw away useful goods','spend carefully and avoid waste','s1 指精打细算、避免浪费。'),Q('frugal',2,2,'A frugal meal is usually?','simple and inexpensive','luxurious and wasteful','inedible by definition','simple and inexpensive','s2 可形容简单朴素的餐食。'),Q('frugal',3,1,'Which choice is frugal?','mending a coat instead of replacing it immediately','discarding a new coat for fashion','buying five unused coats','mending a coat instead of replacing it immediately','修补仍可穿的衣物体现节俭。'),Q('frugal',4,1,'Frugal is closest to?','economical','wasteful','lavish','economical','economical 与 frugal 的节约义接近。')]});
D('fruitful',{etymology:E('Fruitful combines fruit and -ful. It first describes a plant that bears much fruit and extends figuratively to work or discussion that produces good results.','fruitful'),contexts:[C('fruitful.s1','研究合作','The collaboration proved fruitful: each lab shared its data, and together the teams identified a safer treatment protocol.','这次合作卓有成效：各实验室共享数据，团队共同找到了一套更安全的治疗方案。','The collaboration proved fruitful / each lab shared its data / and together the teams identified a safer treatment protocol.','fruitful 在此比喻讨论或努力产生了良好结果。','合作带来实质可用的新方案，符合 s1。')],mistakes:[M('The two-year investigation was fruitful because it produced no results, insights, or recommendations.','The two-year investigation was fruitless because it produced no results or recommendations.','毫无结果的调查不是 fruitful。')],quiz:[Q('fruitful',1,1,'A fruitful discussion is one that?','produces useful results','goes on without any progress','takes place only in an orchard','produces useful results','s1 表示富有成效。'),Q('fruitful',2,2,'A fruitful tree?','bears much fruit','has no blossoms or crops','grows only in a room','bears much fruit','s2 指结果多、多产的植物。'),Q('fruitful',3,1,'Which activity is fruitful?','a meeting that leads to a workable agreement','a debate that reaches no decision','a search that finds nothing','a meeting that leads to a workable agreement','达成可行协议体现活动有成效。'),Q('fruitful',4,1,'Fruitful contrasts with?','fruitless','productive','successful','fruitless','fruitless 表示徒劳，与 fruitful 相对。')]});
D('fruitfulness',{etymology:E('Fruitfulness is formed from fruitful plus -ness. It names fertility or the ability to produce fruit, offspring, or beneficial results.','fruitfulness'),contexts:[C('fruitfulness.s1','土壤评估','The orchard’s fruitfulness improved after the growers restored soil nutrients and introduced pollinator plants between the rows.','种植者恢复土壤养分并在树行间种植传粉植物后，果园的丰产能力有所提高。','The orchard’s fruitfulness improved / after the growers restored soil nutrients / and introduced pollinator plants / between the rows.','fruitfulness 是表示多产或富有成效的抽象名词。','养分恢复和传粉条件改善提高结果能力。')],mistakes:[M('The fruitfulness of the orchard was measured by the fact that no trees flowered or produced any crop.','The fruitfulness of the orchard was measured by the number of healthy flowers and crops it produced.','没有花、没有果实不能表明果园多产。')],quiz:[Q('fruitfulness',1,1,'An orchard’s fruitfulness refers to?','its capacity to produce fruit','the colour of its fences','the age of its tools','its capacity to produce fruit','fruitfulness 可指生殖力或结果能力。'),Q('fruitfulness',2,1,'The fruitfulness of a research programme is shown by?','valuable results it produces','the length of its stationery list','the colour of its office','valuable results it produces','比喻义指产生成果的能力。'),Q('fruitfulness',3,1,'Which suffix turns fruitful into a quality noun?','-ness','-ly','-ize','-ness','fruitful + -ness 构成抽象名词。','word-formation'),Q('fruitfulness',4,1,'A decline in plant fruitfulness may cause?','smaller harvests','more fruit on every branch','a stronger metal frame','smaller harvests','结果能力下降可能导致减产。')]});
D('fruition',{etymology:E('Fruition comes from Latin fruitio “enjoyment, use,” from frui “to enjoy.” In English it commonly means a plan or hope reaching successful completion, or the result achieved.','fruition'),contexts:[C('fruition.s1','建设项目','After years of fundraising and design revisions, the community garden finally came to fruition, opening with accessible paths and shared plots.','经过多年筹款和设计修改，社区花园终于建成开放，设有无障碍小路和共享种植地。','After years of fundraising and design revisions / the community garden finally came to fruition / opening with accessible paths and shared plots.','come to fruition 是固定表达，表示计划最终实现。','长期筹备的花园建成开放，体现实现义 s1。')],mistakes:[M('The garden came to fruition when its plans were abandoned and the land remained empty.','The garden failed to come to fruition when its plans were abandoned and the land remained empty.','计划放弃、土地闲置意味着没有实现。')],quiz:[Q('fruition',1,1,'A long-planned project comes to fruition when it?','is successfully completed','is permanently abandoned','is forgotten before work begins','is successfully completed','s1 指计划或愿望最终实现。'),Q('fruition',2,2,'The fruitions of a campaign are?','the successful results produced by effort','the dates when work began','the problems that prevented any success','the successful results produced by effort','s2 可指努力获得的成果。'),Q('fruition',3,1,'Choose the standard phrase.','come to fruition','come into fruitly','fruition at coming','come to fruition','固定搭配为 come to fruition。','collocation'),Q('fruition',4,1,'Which sentence uses fruition correctly?','Their conservation plan came to fruition after the wetland reopened.','The unfinished plan was fruition by nobody.','Fruition stopped the planning before it began.','Their conservation plan came to fruition after the wetland reopened.','湿地重新开放说明计划获得实现。')]});
D('fruitlessly',{etymology:E('Fruitlessly is formed from fruitless plus -ly; fruitless means producing no useful result. The adverb describes effort that fails to achieve its purpose.','fruitlessly'),contexts:[C('fruitlessly.s1','搜寻记录','The archivist searched fruitlessly for the missing ledger all morning, then found it inside a box labelled with the wrong year.','档案管理员整个上午都徒劳地寻找遗失账簿，后来才在一个标错年份的箱子里找到它。','The archivist searched fruitlessly for the missing ledger all morning / then found it / inside a box labelled with the wrong year.','fruitlessly 修饰 searched，说明搜寻当时没有结果。','先前的搜寻未找到目标，符合无结果地义。')],mistakes:[M('She searched fruitlessly and immediately found the ledger on her first attempt.','She searched fruitlessly for hours and did not find the ledger.','立即找到目标意味着搜寻并非徒劳。')],quiz:[Q('fruitlessly',1,1,'To search fruitlessly is to search?','without finding what one seeks','and find the answer at once','only for fruit','without finding what one seeks','fruitlessly 表示没有成功或结果。'),Q('fruitlessly',2,1,'Which effort was fruitless?','calling every number but reaching no one','calling once and speaking to the right person','sending a message that solved the problem','calling every number but reaching no one','努力没有达到目的，属于 fruitless。'),Q('fruitlessly',3,1,'Fruitlessly is an adverb formed from?','fruitless','fruition','fruitfulness','fruitless','fruitlessly = fruitless + -ly。','word-formation'),Q('fruitlessly',4,1,'The team argued fruitlessly because?','the discussion produced no agreement','they settled the issue quickly','both sides reached a clear compromise','the discussion produced no agreement','无结果的争论符合该副词。')]});
D('frustrated',{etymology:E('Frustrated is the past participle and adjective from frustrate, from Latin frustrari “to disappoint, thwart.” It describes annoyance at blocked aims or a person prevented from succeeding.','frustrated'),contexts:[C('frustrated.s2','职业受阻','The frustrated architect had designed the project for years but could not get permission to begin construction before the funding expired.','这位不得志的建筑师多年设计该项目，却未能在资金到期前取得开工许可。','The frustrated architect had designed the project for years / but could not get permission / to begin construction / before the funding expired.','frustrated 在此表示抱负受阻、事业不得志。','长期准备却因许可和资金受阻，体现 s2。')],mistakes:[M('The frustrated candidate achieved every career goal and felt fully satisfied with the outcome.','The successful candidate achieved every career goal and felt satisfied with the outcome.','目标全实现且满意并非受挫、不得志。')],quiz:[Q('frustrated',1,1,'A frustrated student feels annoyed because?','progress toward a goal is blocked','every task is already finished perfectly','there is nothing they want to do','progress toward a goal is blocked','s1 指想做的事受阻而沮丧。'),Q('frustrated',2,2,'A frustrated artist who cannot find an audience is?','prevented from achieving an ambition','pleased with complete success','a type of painter’s tool','prevented from achieving an ambition','s2 指抱负受阻、不得志。'),Q('frustrated',3,1,'Which sentence uses frustrated as a feeling?','She felt frustrated when the file would not open.','The frustrated file contained no text.','Frustrated is a type of computer.','She felt frustrated when the file would not open.','文件无法打开使人感到烦恼。'),Q('frustrated',4,2,'Someone may be frustrated in a career if?','circumstances prevent their progress','they have reached every goal','they have no professional aims','circumstances prevent their progress','事业发展受阻对应不得志义。')]});
D('frustrating',{etymology:E('Frustrating is the -ing adjective from frustrate, from Latin frustrari “to disappoint or thwart.” It describes something that causes annoyance or repeated loss of confidence.','frustrating'),contexts:[C('frustrating.s2','反复失败','It was frustrating to watch the prototype fail at the same connection each day, despite the team’s repeated repairs and careful tests.','尽管团队反复维修并仔细测试，看着原型每天都在同一连接处失效仍令人泄气。','It was frustrating to watch the prototype fail at the same connection each day / despite the team’s repeated repairs and careful tests.','frustrating 描述引发情绪的事物，to watch 补充具体情境。','反复失败使人灰心，符合屡试屡败义 s2。')],mistakes:[M('The repeated failures were frustrating, yet they gave the team complete confidence and no annoyance.','The repeated failures were frustrating, leaving the team annoyed and less confident.','令人沮丧的失败不会同时使人毫无烦恼、信心十足。')],quiz:[Q('frustrating',1,1,'A frustrating delay causes people to feel?','annoyed because progress is blocked','certain everything is immediate','unrelated to the wait','annoyed because progress is blocked','s1 描述令人恼火、进展受阻的事物。'),Q('frustrating',2,2,'Repeated failed attempts can be frustrating because they?','make people lose confidence','guarantee immediate success','remove every obstacle','make people lose confidence','s2 强调屡败带来的泄气。'),Q('frustrating',3,1,'A frustrating computer error is one that?','blocks the task and causes annoyance','helps finish the task instantly','has no effect on anyone','blocks the task and causes annoyance','错误阻碍任务并引起烦恼。'),Q('frustrating',4,1,'Which sentence uses the adjective correctly?','The unclear instructions were frustrating.','The unclear instructions were frustrated.','The unclear instructions frustratingly people.','The unclear instructions were frustrating.','令人产生烦恼的东西用 frustrating；感受者用 frustrated。','word-choice')]});
D('frustration',{etymology:E('Frustration comes from Latin frustratio, from frustrari “to disappoint, thwart.” It can name the annoyed feeling of blocked effort or the thing that causes that feeling.','frustration'),contexts:[C('frustration.s2','技术障碍','The outdated login system was a constant frustration because it locked users out even when they entered the correct password.','过时的登录系统总让人烦心，因为即使用户输入正确密码，它也会把人锁在账户之外。','The outdated login system was a constant frustration / because it locked users out / even when they entered the correct password.','frustration 在此指令人烦恼的事物，而非人的情绪本身。','系统反复错误锁定用户，是引起烦恼的因素 s2。')],mistakes:[M('The broken login system was a frustration, but it never caused any user annoyance or difficulty.','The broken login system was not a frustration because it caused no annoyance or difficulty.','称之为令人烦恼的因素却又说毫无烦恼，前后矛盾。')],quiz:[Q('frustration',1,1,'Frustration as a feeling is?','annoyance when an aim is blocked','pleasure at completing a goal','a type of login screen','annoyance when an aim is blocked','s1 指受挫时的沮丧感。'),Q('frustration',2,2,'A printer that repeatedly jams can be?','a frustration','a friendship','a fraternal duty','a frustration','s2 指引起烦恼的因素。'),Q('frustration',3,1,'Which person feels frustration?','someone prevented from finishing a desired task','someone who completed the task easily','someone with no task or goal','someone prevented from finishing a desired task','目标受阻会带来挫败感。'),Q('frustration',4,2,'Choose the noun use for a cause of annoyance.','The faulty alarm was a daily frustration.','He felt frustration after the delay.','Frustration is an emotion.','The faulty alarm was a daily frustration.','faulty alarm 作令人烦恼的事物，属于 s2。')]});
D('fulfill',{etymology:E('Fulfill comes from Old English fullfyllan, combining full and fill. It means to carry out a duty or promise completely, or to make a wish or potential real.','fulfill'),contexts:[C('fulfill.s1','履行承诺','The contractor fulfilled the warranty by replacing the damaged tiles within the agreed period and covering the installation cost.','承包商在约定期限内更换了损坏的瓷砖并承担安装费，履行了保修承诺。','The contractor fulfilled the warranty / by replacing the damaged tiles / within the agreed period / and covering the installation cost.','fulfill 作及物动词，直接接需履行的义务、承诺。','依约完成更换并承担费用，体现履行义务义 s1。')],mistakes:[M('The contractor fulfilled the warranty by refusing to repair the damage and ignoring the agreed terms.','The contractor breached the warranty by refusing to repair the damage and ignoring the agreed terms.','拒绝履约与 fulfill 的完成义相反。')],quiz:[Q('fulfill',1,1,'To fulfill a promise is to?','do what was promised','forget that it was made','make it impossible to carry out','do what was promised','s1 指完整履行承诺或义务。'),Q('fulfill',2,2,'To fulfill a dream means to?','make it real or achieve it','write it down and ignore it','prevent it from happening','make it real or achieve it','s2 表示实现愿望、潜能。'),Q('fulfill',3,1,'Choose the natural pattern.','fulfill a requirement','fulfill to a requirement','fulfillment a requirement','fulfill a requirement','fulfill 直接接宾语 requirement。','grammar'),Q('fulfill',4,1,'Which spelling is American English?','fulfill','fulfil','fullfill','fulfill','美国英语常用 fulfill；英式也见 fulfil。','spelling')]});
D('fulfillment',{etymology:E('Fulfillment is formed from fulfill plus -ment. It can mean completing an obligation or achieving a hope, and also the sense of purpose gained from meaningful work.','fulfillment'),contexts:[C('fulfillment.s2','职业满足','After years of volunteering with adult learners, Mara found a sense of fulfillment in helping people gain confidence with reading.','多年为成人学习者做志愿服务后，玛拉从帮助人们建立阅读信心中获得了满足感。','After years of volunteering with adult learners / Mara found a sense of fulfillment / in helping people gain confidence with reading.','a sense of fulfillment 指实现有意义目标后获得的满足感。','帮助他人并获得意义感，符合 s2。')],mistakes:[M('Mara found fulfillment in work that she considered entirely meaningless and deeply dissatisfying.','Mara found no fulfillment in work that she considered meaningless and deeply dissatisfying.','毫无意义且令人不满的工作与获得满足感矛盾。')],quiz:[Q('fulfillment',1,1,'Fulfillment of a contract means?','completion of its obligations','cancellation before it begins','a feeling of cold air','completion of its obligations','s1 指履行或完成要求。'),Q('fulfillment',2,2,'A sense of fulfillment is?','a feeling that one’s work or life has purpose','a list of unpaid bills','a broken promise','a feeling that one’s work or life has purpose','s2 指有意义感带来的满足。'),Q('fulfillment',3,2,'Which activity may bring fulfillment?','helping learners reach a long-held goal','breaking every commitment','repeating an empty task without purpose','helping learners reach a long-held goal','帮助他人实现目标能带来意义和满足。'),Q('fulfillment',4,1,'Choose the standard phrase.','fulfillment of an obligation','fulfillment to an obligation of','fulfillmenting an obligation','fulfillment of an obligation','常用 fulfillment of。','collocation')]});
D('fulfilment',{etymology:E('Fulfilment is the British spelling of fulfillment, formed from fulfil plus -ment. It can mean carrying out a duty or the contentment gained from worthwhile work.','fulfilment'),contexts:[C('fulfilment.s2','志愿服务','She found fulfilment in restoring the village archive, because the work preserved family records that younger residents could still use.','她从修复村庄档案中获得了满足感，因为这项工作保存了年轻居民仍可查阅的家族记录。','She found fulfilment in restoring the village archive / because the work preserved family records / that younger residents could still use.','fulfilment 是英式拼法；find fulfilment in 表示从某事中获得满足。','有价值的档案保护工作带来意义感，符合 s2。')],mistakes:[M('She found fulfilment in the project, but described the work as wholly meaningless and personally empty.','She found no fulfilment in the project because she considered the work meaningless and empty.','认为工作毫无意义与获得满足感相矛盾。')],quiz:[Q('fulfilment',1,1,'Fulfilment of a duty is?','carrying it out as required','ignoring it completely','a kind of refrigerator','carrying it out as required','s1 指履行职责或承诺。'),Q('fulfilment',2,2,'A person finds fulfilment in worthwhile work when it?','gives a sense of purpose and contentment','prevents all effort','has no meaning to them','gives a sense of purpose and contentment','s2 指有意义工作带来的满足。'),Q('fulfilment',3,1,'Which spelling is British English?','fulfilment','fulfillment only','fulfilmant','fulfilment','英式拼法为 fulfilment。','spelling'),Q('fulfilment',4,2,'Choose the natural phrase.','find fulfilment in teaching','find fulfilment to teaching','find fulfilmently at teaching','find fulfilment in teaching','常说 find fulfilment in + 名词或动名词。','collocation')]});
// CHECKPOINT_4
D('full-time',{etymology:E('Full-time combines full and time. It describes employment or work occupying the whole standard working week rather than only part of it.','full-time'),contexts:[C('full-time.s1','岗位说明','The laboratory hired a full-time technician who works five days each week and is responsible for maintaining the instruments.','实验室聘用了一名全职技术员，每周工作五天并负责维护仪器。','The laboratory hired a full-time technician / who works five days each week / and is responsible for maintaining the instruments.','full-time 作复合形容词修饰 technician。','每周承担完整工作周而非兼职，符合义项。')],mistakes:[M('The advertisement called the two-hour-a-week post full-time.','The advertisement called the two-hour-a-week post part-time.','每周只工作两小时不属于全职岗位。')],quiz:[Q('full-time',1,1,'A full-time job usually occupies?','the whole standard working week','one short shift each month','no working hours','the whole standard working week','full-time 指整个标准工作周的工作。'),Q('full-time',2,1,'A full-time employee differs from a part-time employee by?','working the full standard schedule','being unable to receive pay','working only one brief shift','working the full standard schedule','全职与兼职的关键区别是工时。'),Q('full-time',3,1,'Choose the correct compound adjective.','a full-time position','a full timefully position','a position full-timing','a full-time position','作名词前定语时常用连字符。','grammar'),Q('full-time',4,1,'Which person is most likely full-time?','an employee working the standard week','a volunteer attending one hour yearly','a customer visiting once','an employee working the standard week','完成标准工作周的人是全职员工。')]});
D('fullness',{etymology:E('Fullness is formed from full plus -ness. It can mean completeness or the rich, ample quality of sound, flavour, shape, or texture.','fullness'),contexts:[C('fullness.s1','音响评价','The engineer adjusted the speakers to restore the fullness of the cello, whose low notes had sounded thin in the large hall.','工程师调整扬声器以恢复大提琴声音的丰满度；此前它的低音在大厅里听起来单薄。','The engineer adjusted the speakers / to restore the fullness of the cello / whose low notes had sounded thin / in the large hall.','fullness 是抽象名词，可指声音丰富、饱满的质感。','低音由单薄变得丰满体现声音质感义。')],mistakes:[M('The fullness of the recording was praised because every note sounded thin and weak.','The thinness of the recording was criticized because every note sounded weak.','声音单薄与 fullness 的丰富饱满相反。')],quiz:[Q('fullness',1,1,'Fullness in a musical recording means?','a rich, ample sound','complete silence','a missing track','a rich, ample sound','fullness 可指声音的饱满、丰富。'),Q('fullness',2,1,'A sense of fullness in a meal may mean?','a complete or satisfying quality','that the plate is empty','that the food is frozen','a complete or satisfying quality','fullness 也可指充实或丰足的状态。'),Q('fullness',3,1,'Which word forms the noun fullness?','full','frugal','funnel','full','full + -ness 构成抽象名词。','word-formation'),Q('fullness',4,1,'A singer restores the fullness of a note by making it?','richer and more resonant','quieter until inaudible','shorter than silence','richer and more resonant','声音饱满即丰富、有共鸣。')]});
D('fulminate',{etymology:E('Fulminate comes from Latin fulminare “to strike with lightning,” from fulmen “lightning.” It can mean to denounce angrily or to explode with a sudden loud report.','fulminate'),contexts:[C('fulminate.s1','公开批评','The columnist fulminated against the agency’s secret fees, arguing that customers should have been told the full cost before signing.','专栏作者严厉抨击该机构的隐性收费，认为顾客在签约前就应获知全部费用。','The columnist fulminated against the agency’s secret fees / arguing that customers should have been told / the full cost / before signing.','fulminate against 表示激烈、愤怒地抨击。','作者公开猛烈批评隐性收费，对应 s1。')],mistakes:[M('The columnist fulminated against the hidden fees by calmly praising them as transparent and fair.','The columnist fulminated against the hidden fees by condemning them as deceptive.','平静赞扬与愤怒抨击相反。')],quiz:[Q('fulminate',1,1,'To fulminate against a policy is to?','denounce it loudly and angrily','approve it quietly','write it down neutrally','denounce it loudly and angrily','s1 表示严词抨击。'),Q('fulminate',2,2,'A firework may fulminate when it?','explodes with a loud report','melts silently into water','grows on a tree','explodes with a loud report','s2 指突然发出巨响地爆炸。'),Q('fulminate',3,1,'Which pattern is natural?','fulminate against the decision','fulminate the decision against of','fulminate into the decision','fulminate against the decision','动词常与 against 连用表示抨击对象。','collocation'),Q('fulminate',4,2,'A device that fulminates produces?','a sudden loud explosion','a steady quiet hum','a cool stream of water','a sudden loud explosion','爆响、爆炸对应 s2。')]});
D('fulsome',{etymology:E('Fulsome is formed from full and -some, originally meaning abundant or excessive. In current use it often describes praise so overdone that it seems insincere or distasteful.','fulsome'),contexts:[C('fulsome.s1','颁奖致辞','The director’s fulsome praise of the sponsor sounded insincere because it lasted longer than the award speech and mentioned no specific contribution.','主任对赞助人的过度赞美听起来并不真诚，因为致辞比颁奖环节还长，却没有提到任何具体贡献。','The director’s fulsome praise of the sponsor sounded insincere / because it lasted longer than the award speech / and mentioned no specific contribution.','fulsome 修饰 praise，常带过头、肉麻而不可信的贬义。','冗长且缺乏具体依据的赞美显得过度奉承。')],mistakes:[M('Her fulsome praise was brief, restrained, and limited to a factual note of thanks.','Her measured praise was brief, restrained, and limited to a factual note of thanks.','克制简短的感谢不属于过度奉承。')],quiz:[Q('fulsome',1,1,'Fulsome praise is often?','excessive and seemingly insincere','brief and completely neutral','an official safety warning','excessive and seemingly insincere','fulsome 常指过分、肉麻的奉承。'),Q('fulsome',2,1,'A fulsome compliment may make its target feel?','uncomfortable because it is overdone','certain that no praise was offered','physically cold','uncomfortable because it is overdone','过度夸奖可能令人不自在。'),Q('fulsome',3,1,'Which praise is most likely fulsome?','a long exaggerated speech with no specific basis','a short precise note of thanks','a factual list of the award criteria','a long exaggerated speech with no specific basis','夸张且缺少依据的赞美符合该词。'),Q('fulsome',4,1,'Fulsome praise differs from sincere praise because it may be?','overblown and distasteful','specific and proportionate','absent altogether','overblown and distasteful','过度奉承是其常见贬义。')]});
D('fumigate',{etymology:E('Fumigate comes from Latin fumigare “to smoke,” from fumus “smoke.” It means treating a room or container with fumes to kill pests or harmful organisms.','fumigate'),contexts:[C('fumigate.s1','仓库害虫防治','The licensed team sealed the grain store and fumigated it to eliminate insects before new supplies were brought inside.','持证团队封闭粮仓并用熏蒸方式杀虫，之后才把新物资运入。','The licensed team sealed the grain store / and fumigated it / to eliminate insects / before new supplies were brought inside.','fumigate 作及物动词，后接需要熏蒸处理的空间。','密封仓库并用烟剂杀虫符合定义。')],mistakes:[M('The team fumigated the grain store by leaving its doors open and releasing no fumes or pest treatment.','The team fumigated the grain store by sealing it and applying pest-killing fumes.','未使用烟剂或药剂不能称为熏蒸处理。')],quiz:[Q('fumigate',1,1,'To fumigate a room is to?','treat it with fumes to kill pests','paint it with water','cool it with a fan only','treat it with fumes to kill pests','fumigate 指用烟熏或气体处理以杀灭害虫。'),Q('fumigate',2,1,'Why might a warehouse be fumigated?','to eliminate insects or pests','to make its walls brighter','to increase the amount of grain','to eliminate insects or pests','熏蒸可杀灭仓库害虫。'),Q('fumigate',3,1,'Which step is associated with fumigation?','sealing the space during treatment','leaving all doors open so fumes escape','adding fresh fruit to the room','sealing the space during treatment','通常需密闭空间以进行熏蒸。'),Q('fumigate',4,1,'The Latin source fumus means?','smoke','fruit','brother','smoke','fumigate 的词源与 smoke 有关。')]});
D('functional',{etymology:E('Functional is formed from function plus -al; function comes from Latin functio, “performance or execution.” Functional can mean practical and usable, or relating to how something operates.','functional'),contexts:[C('functional.s1','家具设计','The clinic chose functional chairs with washable covers and stable armrests, even though their plain shape was less decorative than the alternatives.','诊所选择了实用的椅子，配有可清洗椅套和稳固扶手，尽管外形不如其他款式美观。','The clinic chose functional chairs / with washable covers and stable armrests / even though their plain shape / was less decorative than the alternatives.','functional 在此表示实用、能很好发挥作用。','易清洁且稳固，实用性优先于装饰效果，符合 s1。')],mistakes:[M('The clinic chose functional chairs that could not support anyone and had no usable parts.','The clinic chose decorative chairs that looked attractive but were not practical to use.','不能承重、无法使用的椅子不符合 functional 的实用义。')],quiz:[Q('functional',1,1,'A functional kitchen is designed to?','work efficiently and meet practical needs','look decorative but be unusable','remain locked at all times','work efficiently and meet practical needs','s1 指实用且能正常发挥用途。'),Q('functional',2,2,'Functional testing examines?','how a system works','its legal ownership only','the colour of its packaging only','how a system works','s2 指与功能运作有关的。'),Q('functional',3,1,'Which chair is functional?','a stable chair with washable fabric for a clinic','a fragile sculpture that cannot be sat on','an empty picture frame','a stable chair with washable fabric for a clinic','适合实际使用、易清洁的椅子有实用功能。'),Q('functional',4,2,'A functional requirement describes?','what a product or system must do','who owns the building','what colour the sky is','what a product or system must do','功能需求说明产品需要完成的操作。')]});
D('functionalism',{etymology:E('Functionalism is formed from function plus -al and -ism. It names approaches that understand design, society, or the mind through the roles and purposes their parts serve.','functionalism'),contexts:[C('functionalism.s1','设计理论','The architecture course introduced functionalism through buildings whose layout and materials were chosen for use rather than ornament.','建筑课程通过介绍布局和材料以实用而非装饰为选择依据的建筑，讲解了功能主义。','The architecture course introduced functionalism / through buildings whose layout and materials / were chosen for use / rather than ornament.','functionalism 是理论或思想流派名词。','强调用途决定设计，体现功能主义观点。')],mistakes:[M('The lecture defined functionalism as the view that decoration must always matter more than a building’s use.','The lecture defined functionalism as the view that a building’s function should guide its design.','把装饰置于功能之上与功能主义核心相反。')],quiz:[Q('functionalism',1,1,'In design, functionalism emphasizes?','the purpose and use of an object or building','ornament regardless of use','the age of the designer','the purpose and use of an object or building','功能主义重视用途和功能。'),Q('functionalism',2,1,'A functionalist architect may choose a layout based on?','how people will use the space','the number of decorative statues alone','a random colour preference','how people will use the space','空间用途会影响功能主义设计。'),Q('functionalism',3,1,'Functionalism is a?','theoretical approach','type of household refrigerator','verb tense','theoretical approach','-ism 常构成思想或理论流派名称。'),Q('functionalism',4,1,'Which building best illustrates functionalism?','a school planned around safe, efficient movement','a hall designed only for decoration and never used','a wall with no entrances or purpose','a school planned around safe, efficient movement','布局由实际使用需求决定体现功能主义。')]});
D('functionality',{etymology:E('Functionality is formed from functional plus -ity. In computing and product design it means the set of operations or features a system can perform.','functionality'),contexts:[C('functionality.s1','软件评估','The review praised the app’s offline functionality because travellers could save maps and search them without an internet connection.','评测称赞这款应用的离线功能，因为旅行者可以保存地图并在没有网络时搜索。','The review praised the app’s offline functionality / because travellers could save maps / and search them / without an internet connection.','functionality 是系统可执行功能或操作的集合。','保存并搜索离线地图是应用具备的操作功能。')],mistakes:[M('The app’s functionality improved when every feature was removed and users could no longer save or search maps.','The app’s functionality decreased when every feature was removed and users could no longer save or search maps.','删除所有功能会降低而非提高 functionality。')],quiz:[Q('functionality',1,1,'A product’s functionality means?','the operations or features it can perform','the colour of its advertising','the size of its shipping box','the operations or features it can perform','functionality 指产品具备的功能。'),Q('functionality',2,1,'Offline functionality lets a user?','use features without an internet connection','turn a screen into paper','avoid every software update forever','use features without an internet connection','离线功能使用户断网时仍能使用部分功能。'),Q('functionality',3,1,'Which change adds functionality to a map app?','adding route search and saved maps','removing every button','changing only the logo colour','adding route search and saved maps','新增搜索、保存操作会增加功能。'),Q('functionality',4,1,'Functionality is especially common in discussions of?','software and product features','funeral customs only','weather patterns','software and product features','该词常用于产品和软件评价。')]});
D('functioning',{etymology:E('Functioning is formed from function plus -ing. As a noun it can mean the process or quality of working; as a modifier it describes something operating.','functioning'),contexts:[C('functioning.s1','系统检查','The technician monitored the functioning of the backup pump during the outage to confirm that it could maintain water pressure.','停电期间，技术员监测备用水泵的运行情况，以确认它能维持水压。','The technician monitored the functioning of the backup pump / during the outage / to confirm / that it could maintain water pressure.','functioning 在此作名词，指设备运行过程或工作状况。','检查水泵是否能正常维持水压，体现运作义。')],mistakes:[M('The report described the functioning pump as unable to start, move water, or perform its purpose.','The report described the non-functioning pump as unable to start or move water.','能正常工作的泵不可能完全无法启动或输水。')],quiz:[Q('functioning',1,1,'The functioning of a pump refers to?','the way it operates','its colour alone','the name of its maker','the way it operates','functioning 指设备运作情况。'),Q('functioning',2,1,'A functioning emergency light?','works when needed','is permanently broken','is only a drawing','works when needed','作定语时 functioning 表示能正常工作的。'),Q('functioning',3,1,'Which phrase is natural?','the functioning of the system','the system functioningness','functioning to the system of','the functioning of the system','常用 the functioning of。','grammar'),Q('functioning',4,1,'A check of a machine’s functioning tests whether it?','works as intended','has a popular name','was painted recently','works as intended','检查运行状况就是检查是否按预期工作。')]});
D('fund-raising',{etymology:E('Fund-raising combines fund and raising. It names organized efforts to collect money for a stated cause or institution.','fund-raising'),contexts:[C('fund-raising.s1','学校募款','The school’s fund-raising campaign paid for new library shelves, with volunteers explaining the project to families at the weekend fair.','学校的筹款活动为图书馆添置了新书架，志愿者在周末集市向家庭介绍项目。','The school’s fund-raising campaign paid for new library shelves / with volunteers explaining the project / to families at the weekend fair.','fund-raising 作名词或定语，指为特定用途筹款。','筹集捐款购买书架，符合募捐义。')],mistakes:[M('The fund-raising campaign refused donations and returned every contribution to its supporters.','The campaign raised funds by accepting donations for the library shelves.','拒绝并退还全部捐款不能构成筹款活动。')],quiz:[Q('fund-raising',1,1,'Fund-raising is organized to?','collect money for a purpose','spend money without a plan','store food in a fridge','collect money for a purpose','fund-raising 指为特定用途筹集资金。'),Q('fund-raising',2,1,'A charity may use fund-raising to?','pay for its services or projects','close every donation channel','change its members’ names','pay for its services or projects','筹款所得可支持慈善服务或项目。'),Q('fund-raising',3,1,'Choose the natural phrase.','a fund-raising campaign','a raising-fundly campaign','a fund-raised of campaign','a fund-raising campaign','常见搭配为 fund-raising campaign。'),Q('fund-raising',4,1,'A school holds a fund-raiser when it needs?','money for a stated project','new grammar rules','a warmer climate','money for a stated project','筹款活动的目标是募集资金。')]});
D('fundamentally',{etymology:E('Fundamentally is formed from fundamental plus -ly. Fundamental comes from Latin fundamentum “foundation,” from fundus “bottom.” The adverb means at the most basic level or in essential fact.','fundamentally'),contexts:[C('fundamentally.s1','方案比较','Although the two transit proposals use different vehicles, they are fundamentally similar: both connect the outer district to the central hospital.','尽管两项交通方案使用不同车辆，它们在根本上相似：两者都把外围城区连接到中心医院。','Although the two transit proposals use different vehicles / they are fundamentally similar / both connect the outer district / to the central hospital.','fundamentally 修饰 similar，强调最基本、重要的方面。','两方案交通工具不同，但核心目的相同，体现 s1。')],mistakes:[M('The two systems were fundamentally identical because their core goals were completely different.','The two systems were fundamentally different because their core goals were completely different.','核心目标完全不同与“根本相同”矛盾。')],quiz:[Q('fundamentally',1,1,'Two plans that are fundamentally alike are alike?','in their basic and important features','only in the colour of a logo','by accident for one minute','in their basic and important features','s1 表示在根本、基础方面。'),Q('fundamentally',2,2,'If a claim is fundamentally true, it is?','actually true when the basic facts are considered','true only in its spelling','a statement about furniture','actually true when the basic facts are considered','s2 强调依据基本事实实质上成立。'),Q('fundamentally',3,1,'Choose the natural phrase.','fundamentally different','fundamental different','fundamentally difference','fundamentally different','副词 fundamentally 修饰形容词 different。','grammar'),Q('fundamentally',4,1,'A fundamentally new approach changes?','the basic way the problem is handled','only the colour of a folder','nothing important at all','the basic way the problem is handled','根本性的新方法改变处理问题的基础方式。')]});
D('funerary',{etymology:E('Funerary comes from Latin funerarius, from funus “funeral, burial.” It describes objects, customs, or structures used for funerals and burial.','funerary'),contexts:[C('funerary.s1','考古研究','The archaeologists documented funerary objects placed beside the burial chamber, including lamps and bowls intended for the deceased.','考古人员记录了墓室旁放置的丧葬用品，包括为逝者准备的灯和碗。','The archaeologists documented funerary objects / placed beside the burial chamber / including lamps and bowls / intended for the deceased.','funerary 作定语修饰 objects，表示用于丧葬仪式。','物品放在墓室旁并为逝者准备，属于丧葬用品。')],mistakes:[M('The museum called the tools funerary objects although they were used daily for farming and never connected with burial.','The museum called the lamps and bowls placed in the tomb funerary objects.','日常农具且与葬礼无关，不符合 funerary。')],quiz:[Q('funerary',1,1,'Funerary objects are connected with?','funerals and burial','school examinations','shipbuilding','funerals and burial','funerary 表示丧葬相关的。'),Q('funerary',2,1,'A funerary monument is built to?','commemorate or mark a burial','store fresh fish','teach a language','commemorate or mark a burial','纪念或标记墓葬的建筑属于 funerary。'),Q('funerary',3,1,'Which phrase is natural?','funerary customs','funerary weather forecast','funerarily coffin','funerary customs','funerary 可修饰 customs，指丧葬习俗。'),Q('funerary',4,1,'An object found in a tomb and used in a burial rite is?','funerary','frugal','furry','funerary','与墓葬仪式有关的物品属丧葬用品。')]});
D('funereal',{etymology:E('Funereal comes from Latin funereus, related to funus “funeral.” Unlike the neutral funerary, it commonly describes a mood, colour, or pace that feels dark and mournful.','funereal'),contexts:[C('funereal.s1','音乐评论','The play ended with a funereal procession and slow, mournful music that left the audience silent as the curtain fell.','戏剧以送葬般的队伍和缓慢哀伤的音乐收尾，幕布落下时观众一片沉默。','The play ended with a funereal procession / and slow, mournful music / that left the audience silent / as the curtain fell.','funereal 修饰 procession，带有阴沉、哀悼的情绪色彩。','缓慢哀伤、仿佛葬礼的队伍对应义项。')],mistakes:[M('The lively brass band and bright dancing made the parade feel funereal and mournful.','The lively brass band and bright dancing made the parade feel festive rather than funereal.','欢快舞蹈与明亮音乐不呈现送葬般的阴沉氛围。')],quiz:[Q('funereal',1,1,'A funereal atmosphere feels?','dark and mournful','cheerful and playful','brightly comic','dark and mournful','funereal 表示像葬礼般悲凉阴沉。'),Q('funereal',2,1,'Which music is funereal?','slow, solemn music at a memorial','a lively dance tune','a humorous jingle','slow, solemn music at a memorial','庄严哀伤的音乐有送葬般气氛。'),Q('funereal',3,1,'Funereal differs from funerary because funereal often describes?','a gloomy mood or style','the legal paperwork of a burial only','a plant disease','a gloomy mood or style','funereal 常描述悲凉气氛；funerary 可中性指丧葬用途。'),Q('funereal',4,1,'Choose the natural phrase.','a funereal silence','a funereal birthday cake with fireworks','funerally silence of','a funereal silence','funereal silence 表示悲凉沉寂。')]});
D('fungal',{etymology:E('Fungal is formed from fungus plus -al. Fungus comes from Latin fungus, a name for a mushroom; fungal means caused by or consisting of fungi.','fungal'),contexts:[C('fungal.s1','作物病害','The leaves showed a fungal infection, so the grower removed the affected plants and improved air circulation in the greenhouse.','叶片出现真菌感染，因此种植者清除了受影响的植株，并改善温室通风。','The leaves showed a fungal infection / so the grower removed the affected plants / and improved air circulation / in the greenhouse.','fungal 作定语修饰 infection，表示由真菌造成。','病害由真菌引起，通风改善有助于降低问题。')],mistakes:[M('The fungal infection was caused by a virus and could not involve any fungus.','The viral infection was caused by a virus and did not involve a fungus.','由病毒造成的感染不应称为 fungal。')],quiz:[Q('fungal',1,1,'A fungal infection is caused by?','a fungus','a metal fragment','a language error','a fungus','fungal 指由真菌造成或与真菌有关。'),Q('fungal',2,1,'A fungal disease on a plant may affect its?','leaves or roots','paper labels only','ship’s funnel','leaves or roots','植物可患真菌性病害。'),Q('fungal',3,1,'Which noun does fungal come from?','fungus','funnel','frost','fungus','fungal 由 fungus 派生。','word-formation'),Q('fungal',4,1,'A fungal culture contains?','fungi growing in a medium','only clean water','a group of ships','fungi growing in a medium','真菌培养物中生长的是 fungi。')]});
D('fungicide',{etymology:E('Fungicide combines fungus and the Latin-derived ending -cide, from caedere “to kill.” It names a substance used to destroy or control fungal pests.','fungicide'),contexts:[C('fungicide.s1','园艺防治','The gardener applied a fungicide to the rose leaves after identifying mildew, following the product label and keeping it away from nearby ponds.','园丁确认玫瑰叶片患有霉病后按产品标签施用杀真菌剂，并使其远离附近池塘。','The gardener applied a fungicide to the rose leaves / after identifying mildew / following the product label / and keeping it away from nearby ponds.','fungicide 是用于杀灭或控制真菌的物质。','霉病由真菌引起，施用相应用剂符合定义。')],mistakes:[M('The gardener used an insecticide as a fungicide to kill mildew, although the product controlled insects and had no fungal target.','The gardener used a fungicide to control mildew on the rose leaves.','只针对昆虫的杀虫剂不是杀真菌剂。')],quiz:[Q('fungicide',1,1,'A fungicide is used to?','destroy or control fungi','kill weeds only','feed a fish','destroy or control fungi','fungicide 指杀灭或控制真菌的药剂。'),Q('fungicide',2,1,'A gardener might use a fungicide against?','mildew on leaves','a broken fence','a language mistake','mildew on leaves','霉菌病害可用杀真菌剂控制。'),Q('fungicide',3,1,'The ending -cide means?','killing or destroying','growing quickly','looking forward','killing or destroying','-cide 表示杀灭。','word-formation'),Q('fungicide',4,1,'Which is a fungicide target?','a fungal disease on a crop','a loose door hinge','a ship’s smoke stack','a fungal disease on a crop','fungicide 针对真菌性病害。')]});
D('funk',{etymology:E('Funk for a state of fear or low spirits is recorded in English; its origin is uncertain and separate from the musical genre sense. The related verb means to avoid a duty or danger out of fear.','funk'),contexts:[C('funk.s1','情绪低落','After the rejected grant application, Jo spent a week in a funk and could not bring herself to reopen the project plan.','资助申请被拒后，乔有一周情绪低落，提不起劲重新打开项目计划。','After the rejected grant application / Jo spent a week in a funk / and could not bring herself / to reopen the project plan.','in a funk 是固定表达，指害怕、沮丧或低落的状态。','遭拒后情绪消沉并停滞，符合 s1。')],mistakes:[M('After the rejection, Jo was in a funk, cheerful and eager to restart the work immediately.','After the rejection, Jo was in high spirits and eager to restart the work immediately.','精神愉快、充满干劲与 funk 的低落状态相反。')],quiz:[Q('funk',1,1,'Being in a funk means being?','in a state of fear or low spirits','in a ship’s engine room','celebrating a success','in a state of fear or low spirits','s1 指恐惧或沮丧的情绪状态。'),Q('funk',2,2,'To funk a dangerous duty is to?','avoid it because one is afraid','perform it courageously','write it in a report','avoid it because one is afraid','s2 作动词表示因害怕而逃避职责。'),Q('funk',3,1,'Which sentence uses funk as a noun?','He stayed in a funk after the setback.','He funked the assignment by refusing it.','The funked were in the room.','He stayed in a funk after the setback.','in a funk 中 funk 是名词。'),Q('funk',4,2,'A worker who funks a dangerous task?','backs away from it out of fear','completes it despite fear','assigns it to a trained colleague','backs away from it out of fear','动词义强调畏惧而逃避。')]});
D('funnel',{etymology:E('Funnel came through Old French fonel from medieval Latin fundibulum, a pouring vessel, related to fundere “to pour.” It names a wide-topped utensil, a ship’s smoke stack, or directing flow through a narrow space.','funnel'),contexts:[C('funnel.s3','人流引导','Stewards used barriers to funnel concertgoers through two narrow gates, keeping the emergency lane clear as the crowd entered.','工作人员用隔离栏把观众引导通过两道窄门，同时在入场时保持应急通道畅通。','Stewards used barriers to funnel concertgoers through two narrow gates / keeping the emergency lane clear / as the crowd entered.','funnel 在此作及物动词，表示引导人流通过狭窄通道。','人群被集中并导向窄门，符合 s3。')],mistakes:[M('The stewards funnelled the crowd by spreading everyone across the entire field and preventing movement toward the gates.','The stewards funnelled the crowd by guiding it through the narrow gates.','把人群分散并阻止其向出口移动，不是 funnel through。')],quiz:[Q('funnel',1,1,'A kitchen funnel helps pour liquid into?','a narrow-necked bottle','a wide open field','a ship’s chimney only','a narrow-necked bottle','s1 是上宽下窄的漏斗。'),Q('funnel',2,2,'A ship’s funnel is its?','smoke chimney','anchor','steering wheel','smoke chimney','s2 指船上的烟囱。'),Q('funnel',3,3,'To funnel people through a gate is to?','direct them through a narrow passage','spread them randomly across a field','stop them from moving anywhere','direct them through a narrow passage','s3 表示引导人或物集中通过狭窄处。'),Q('funnel',4,1,'Which object is a funnel?','a wide-mouth tool with a narrow tube below','a flat cloth sheet','a refrigerated cabinet','a wide-mouth tool with a narrow tube below','漏斗上宽下窄，便于导入液体。')]});
D('furnishing',{etymology:E('Furnishing is formed from furnish plus -ing. Furnish came through French fournir “to provide”; as a noun, furnishing can mean room furniture or the act of supplying what is needed.','furnishing'),contexts:[C('furnishing.s1','室内陈设','The apartment’s furnishings included a desk, two chairs, lamps, and curtains, all chosen to fit the small rooms.','公寓的家具陈设包括书桌、两把椅子、灯和窗帘，都是为小房间挑选的。','The apartment’s furnishings included a desk, two chairs, lamps, and curtains / all chosen / to fit the small rooms.','furnishings 常用复数，指房间里的家具和配套用品。','清单列出室内家具及陈设，符合 s1。')],mistakes:[M('The room’s furnishings consisted only of an empty wall, with no furniture or fittings.','The room’s furnishings consisted of a desk, chairs, and lamps.','空房间没有家具或陈设。')],quiz:[Q('furnishing',1,1,'A room’s furnishings are its?','furniture and fittings','weather conditions','legal documents only','furniture and fittings','s1 通常以复数 furnishings 指家具陈设。'),Q('furnishing',2,2,'The furnishing of emergency supplies means?','the act of providing what is needed','decorating a room with sofas','removing all resources','the act of providing what is needed','s2 指供应、提供所需物品的行为。'),Q('furnishing',3,1,'Which list contains furnishings?','a table, chairs, and lamps','rain, wind, and frost','fossils and fungi','a table, chairs, and lamps','桌椅和灯是家具陈设。'),Q('furnishing',4,1,'Choose the natural phrase.','the furnishings of the flat','the flat furnishingly','furnishings of to the flat','the furnishings of the flat','常说 the furnishings of a room。','grammar')]});
D('furor',{etymology:E('Furor is a direct borrowing from Latin furor “rage, fury,” from furere “to rage.” It describes a sudden wave of angry or excited public reaction.','furor'),contexts:[C('furor.s1','公众反应','The proposed fare increase caused a furor among commuters, who filled the public hearing and demanded a delay.','拟议中的票价上涨在通勤者中引发公愤，他们挤满公众听证会并要求推迟实施。','The proposed fare increase caused a furor among commuters / who filled the public hearing / and demanded a delay.','cause a furor 表示引发强烈、公开的愤怒反应。','公众聚集抗议票价上涨，体现突然的群体反应。')],mistakes:[M('The announcement caused a furor, but the public reaction was completely calm and went unnoticed.','The announcement caused little reaction because the public remained calm.','毫无关注、平静无事与 furor 的强烈反响相反。')],quiz:[Q('furor',1,1,'A public furor is?','a sudden wave of strong public reaction','a quiet private note','a type of office furniture','a sudden wave of strong public reaction','furor 指突然爆发的公众激烈反应。'),Q('furor',2,1,'A controversial decision may cause a furor by?','making many people react angrily','being ignored by everyone','improving the weather','making many people react angrily','争议决定可能引发公众愤怒。'),Q('furor',3,1,'Choose the natural phrase.','cause a furor','furor of to cause','causing furorly','cause a furor','常用 cause a furor。','collocation'),Q('furor',4,1,'The Latin source of furor refers to?','rage or fury','fresh water','a small fruit','rage or fury','furor 源自拉丁语“愤怒、狂怒”。')]});
D('furry',{etymology:E('Furry is formed from fur plus -y. Fur comes through French from Germanic words for animal hair; furry describes a surface covered with fur or having a fur-like texture.','furry'),contexts:[C('furry.s1','动物外观','The rescued kitten had a furry coat that trapped warmth, so the shelter placed a light blanket in its basket overnight.','获救的小猫有一身蓬松毛皮，能留住温暖，因此收容所夜里在它的篮子里放了条薄毯。','The rescued kitten had a furry coat / that trapped warmth / so the shelter placed a light blanket / in its basket overnight.','furry 修饰 coat，表示覆有毛皮或毛茸茸的质地。','猫身上的柔软毛发构成 furry coat。')],mistakes:[M('The furry kitten was completely hairless, smooth as glass, and had no coat.','The hairless kitten was smooth as glass and had no coat.','无毛、光滑与 furry 的毛茸茸特征相反。')],quiz:[Q('furry',1,1,'A furry animal is?','covered with fur','made of glass','without any hair','covered with fur','furry 表示覆有毛皮。'),Q('furry',2,1,'A furry blanket feels?','soft and fur-like','sharp like broken glass','wet like a river','soft and fur-like','该形容词也可描述类似毛皮的质感。'),Q('furry',3,1,'Which noun is formed with -y in furry?','fur','ferry','fury','fur','furry 由 fur 加 -y 构成。','word-formation'),Q('furry',4,1,'Choose the natural phrase.','a furry coat','a furried coat','furryly coat','a furry coat','furry 可修饰 coat，表示毛茸茸的。','grammar')]});

})();
